IF ((STATE = 0) AND NOT(PREV_IN) AND IN)   (* found rising edge on IN *)
THEN
  (* start timer... *)
  STATE := 1;
  Q := TRUE;
  START_TIME := CURRENT_TIME;

ELSIF (STATE = 1)
THEN
  IF ((START_TIME + PT) <= CURRENT_TIME)
  THEN
    STATE := 2;
    Q := FALSE;
    ET := PT;
  ELSE
    ET := CURRENT_TIME - START_TIME;
  END_IF;
END_IF;

IF ((STATE = 2) AND NOT(IN))
THEN
  ET := T#0s;
  STATE := 0;
END_IF;

