{__SET_VAR(data__->,CURRENT_TIME,,__CURRENT_TIME)}

IF ((STATE = 0) AND PREV_IN AND NOT(IN))   (* found falling edge on IN *)
THEN
  (* start timer... *)
  STATE := 1;
  START_TIME := CURRENT_TIME;

ELSE
  (* STATE is 1 or 2 !! *)
  IF (IN)
  THEN
    ET := T#0s;
    STATE := 0;

  ELSIF (STATE = 1)
  THEN
    IF ((START_TIME + PT) <= CURRENT_TIME)
    THEN
      STATE := 2;
      ET := PT;
    ELSE
      ET := CURRENT_TIME - START_TIME;
    END_IF;
  END_IF;

END_IF;

Q := IN OR (STATE = 1);
