        Active := FALSE;
        InSync := FALSE;
        CommandAborted := FALSE;
        Error := FALSE;
        ErrorID := WORD#16#0000;
    ELSE
        Busy := FALSE;
        Active := FALSE;
        InSync := FALSE;
        EndOfProfile := FALSE;
        AcceptedCommandID := UINT#0;
        WasActive := FALSE;
    END_IF;
END_IF;
