(* OSCAT BASIC 3.33 Chapter 5 Mathematics helpers. *)

FUNCTION ACOSH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ACOSH := LN(SQRT(X * X - 1.0) + X);
END_FUNCTION

FUNCTION ACOTH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ACOTH := LN((X + 1.0) / (X - 1.0)) * 0.5;
END_FUNCTION

FUNCTION AGDF : REAL
VAR_INPUT
    X : REAL;
END_VAR
AGDF := LN((1.0 + SIN(X)) / COS(X));
END_FUNCTION

FUNCTION ASINH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ASINH := LN(SQRT(X * X + 1.0) + X);
END_FUNCTION

FUNCTION ATAN2 : REAL
VAR_INPUT
    Y : REAL;
    X : REAL;
END_VAR
IF X > 0.0 THEN
    ATAN2 := ATAN(Y / X);
ELSIF X < 0.0 THEN
    IF Y >= 0.0 THEN
        ATAN2 := ATAN(Y / X) + MATH.PI;
    ELSE
        ATAN2 := ATAN(Y / X) - MATH.PI;
    END_IF;
ELSIF Y > 0.0 THEN
    ATAN2 := MATH.PI05;
ELSIF Y < 0.0 THEN
    ATAN2 := -MATH.PI05;
ELSE
    ATAN2 := 0.0;
END_IF;
END_FUNCTION

FUNCTION ATANH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ATANH := LN((X + 1.0) / (1.0 - X)) * 0.5;
END_FUNCTION

FUNCTION BETA : REAL
VAR_INPUT
    X : REAL;
    Y : REAL;
END_VAR
BETA := GAMMA(X := X) * GAMMA(X := Y) / GAMMA(X := X + Y);
END_FUNCTION

FUNCTION BINOM : DINT
VAR_INPUT
    N : INT;
    K : INT;
END_VAR
VAR
    Result : DINT;
    WorkN : INT;
    WorkK : INT;
    I : INT;
END_VAR
WorkN := N;
WorkK := K;
IF 2 * WorkK > WorkN THEN
    WorkK := WorkN - WorkK;
END_IF;
IF WorkK > WorkN THEN
    BINOM := DINT#0;
ELSIF WorkK = 0 OR WorkK = WorkN THEN
    BINOM := DINT#1;
ELSIF WorkK = 1 THEN
    BINOM := INT_TO_DINT(WorkN);
ELSE
    Result := INT_TO_DINT(WorkN);
    WorkN := WorkN + 1;
    FOR I := 2 TO WorkK DO
        Result := Result * INT_TO_DINT(WorkN - I) / INT_TO_DINT(I);
    END_FOR;
    BINOM := Result;
END_IF;
END_FUNCTION

FUNCTION CAUCHY : REAL
VAR_INPUT
    X : REAL;
    T : REAL;
    U : REAL;
END_VAR
VAR
    Temp : REAL;
END_VAR
Temp := X - T;
CAUCHY := MATH.PI_INV * U / (U * U + Temp * Temp);
END_FUNCTION

FUNCTION CAUCHYCD : REAL
VAR_INPUT
    X : REAL;
    T : REAL;
    U : REAL;
END_VAR
CAUCHYCD := 0.5 + MATH.PI_INV * ATAN((X - T) / U);
END_FUNCTION

FUNCTION CEIL : INT
VAR_INPUT
    X : REAL;
END_VAR
CEIL := REAL_TO_INT(X);
IF INT_TO_REAL(CEIL) < X THEN
    CEIL := CEIL + 1;
END_IF;
END_FUNCTION

FUNCTION CEIL2 : DINT
VAR_INPUT
    X : REAL;
END_VAR
CEIL2 := REAL_TO_DINT(X);
IF DINT_TO_REAL(CEIL2) < X THEN
    CEIL2 := CEIL2 + 1;
END_IF;
END_FUNCTION

FUNCTION CMP : BOOL
VAR_INPUT
    X : REAL;
    Y : REAL;
    N : INT;
END_VAR
VAR
    ScaleFactor : REAL;
    LogValue : REAL;
    DecadeExponent : INT;
    XDigits : DINT;
    YDigits : DINT;
END_VAR
ScaleFactor := ABS(X);
IF ScaleFactor > 0.0 THEN
    LogValue := LOG(ScaleFactor);
    DecadeExponent := FLOOR(X := LogValue) - N + 1;
    ScaleFactor := EXP10(X := INT_TO_REAL(DecadeExponent));
    XDigits := FLOOR2(X := X / ScaleFactor);
    YDigits := FLOOR2(X := Y / ScaleFactor);
    CMP := XDigits = YDigits;
ELSE
    CMP := X = Y;
END_IF;
END_FUNCTION

FUNCTION COSH : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    T : REAL;
END_VAR
T := EXP(X);
COSH := (1.0 / T + T) * 0.5;
END_FUNCTION

FUNCTION COTH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    COTH := 1.0;
ELSIF X < -20.0 THEN
    COTH := -1.0;
ELSE
    COTH := 1.0 + 2.0 / (EXP(X * 2.0) - 1.0);
END_IF;
END_FUNCTION

FUNCTION D_TRUNC : DINT
VAR_INPUT
    X : REAL;
END_VAR
D_TRUNC := REAL_TO_DINT(X);
IF X > 0.0 THEN
    IF DINT_TO_REAL(D_TRUNC) > X THEN
        D_TRUNC := D_TRUNC - 1;
    END_IF;
ELSE
    IF DINT_TO_REAL(D_TRUNC) < X THEN
        D_TRUNC := D_TRUNC + 1;
    END_IF;
END_IF;
END_FUNCTION

FUNCTION DEC1 : INT
VAR_INPUT
    X : INT;
    N : INT;
END_VAR
IF X = 0 THEN
    DEC1 := N - 1;
ELSE
    DEC1 := X - 1;
END_IF;
END_FUNCTION

FUNCTION DEG : REAL
VAR_INPUT
    RAD : REAL;
END_VAR
DEG := MODR(IN := 57.29577951308232 * RAD, DIVI := 360.0);
END_FUNCTION

FUNCTION DIFFER : BOOL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    X : REAL;
END_VAR
DIFFER := ABS(IN1 - IN2) > X;
END_FUNCTION

FUNCTION ERF : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    X2 : REAL;
    AX2 : REAL;
END_VAR
X2 := X * X;
AX2 := 0.147 * X2 + 1.0;
ERF := SQRT(1.0 - EXP(-X2 * ((0.27323954473516 + AX2) / AX2))) * INT_TO_REAL(SGN(X := X));
END_FUNCTION

FUNCTION ERFC : REAL
VAR_INPUT
    X : REAL;
END_VAR
ERFC := 1.0 - ERF(X := X);
END_FUNCTION

FUNCTION EVEN : BOOL
VAR_INPUT
    IN : DINT;
END_VAR
EVEN := (IN MOD 2) = 0;
END_FUNCTION

FUNCTION EXP10 : REAL
VAR_INPUT
    X : REAL;
END_VAR
EXP10 := EXP(X * 2.30258509299405);
END_FUNCTION

FUNCTION EXPN : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
VAR
    Base : REAL;
    Exponent : INT;
    NegativeExponent : BOOL;
END_VAR
Base := X;
Exponent := N;
NegativeExponent := Exponent < 0;
Exponent := ABS(Exponent);
IF (Exponent MOD 2) = 1 THEN
    EXPN := Base;
ELSE
    EXPN := 1.0;
END_IF;
Exponent := Exponent / 2;
WHILE Exponent > 0 DO
    Base := Base * Base;
    IF (Exponent MOD 2) = 1 THEN
        EXPN := EXPN * Base;
    END_IF;
    Exponent := Exponent / 2;
END_WHILE;
IF NegativeExponent THEN
    EXPN := 1.0 / EXPN;
END_IF;
END_FUNCTION

FUNCTION FACT : DINT
VAR_INPUT
    X : INT;
END_VAR
VAR
    I : INT;
END_VAR
IF X < 0 OR X > 12 THEN
    FACT := -1;
ELSIF X < 2 THEN
    FACT := 1;
ELSE
    FACT := 1;
    FOR I := 2 TO X DO
        FACT := FACT * INT_TO_DINT(I);
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION FIB : DINT
VAR_INPUT
    X : INT;
END_VAR
VAR
    WorkX : INT;
    T1 : DINT;
    T2 : DINT;
END_VAR
WorkX := X;
IF WorkX < 0 OR WorkX > 46 THEN
    FIB := -1;
ELSIF WorkX < 2 THEN
    FIB := INT_TO_DINT(WorkX);
ELSE
    T2 := 1;
    WHILE WorkX > 3 DO
        WorkX := WorkX - 2;
        T1 := T1 + T2;
        T2 := T1 + T2;
    END_WHILE;
    IF WorkX > 2 THEN
        T1 := T1 + T2;
    END_IF;
    FIB := T1 + T2;
END_IF;
END_FUNCTION

FUNCTION FLOOR : INT
VAR_INPUT
    X : REAL;
END_VAR
FLOOR := REAL_TO_INT(X);
IF INT_TO_REAL(FLOOR) > X THEN
    FLOOR := FLOOR - 1;
END_IF;
END_FUNCTION

FUNCTION FLOOR2 : DINT
VAR_INPUT
    X : REAL;
END_VAR
FLOOR2 := REAL_TO_DINT(X);
IF DINT_TO_REAL(FLOOR2) > X THEN
    FLOOR2 := FLOOR2 - 1;
END_IF;
END_FUNCTION

FUNCTION FRACT : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    IntegerPart : DINT;
END_VAR
IF ABS(X) < 2.0E9 THEN
    IntegerPart := D_TRUNC(X := X);
    FRACT := X - DINT_TO_REAL(IntegerPart);
ELSE
    FRACT := 0.0;
END_IF;
END_FUNCTION

FUNCTION GAMMA : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 0.0 THEN
    GAMMA := SQRT(MATH.PI2 / X) * EXPT(MATH.E_INV * (X + 1.0 / (12.0 * X - 0.1 / X)), X);
END_IF;
END_FUNCTION

FUNCTION GAUSS : REAL
VAR_INPUT
    X : REAL;
    U : REAL;
    SI : REAL;
END_VAR
VAR
    Temp : REAL;
    SIInv : REAL;
END_VAR
IF SI = 0.0 THEN
    GAUSS := 0.0;
ELSE
    Temp := X - U;
    SIInv := 1.0 / SI;
    GAUSS := EXP(Temp * Temp * SIInv * SIInv * -0.5) * 0.39894228 * SIInv;
END_IF;
END_FUNCTION

FUNCTION GAUSSCD : REAL
VAR_INPUT
    X : REAL;
    U : REAL;
    SI : REAL;
END_VAR
IF SI = 0.0 THEN
    IF X < U THEN
        GAUSSCD := 0.0;
    ELSE
        GAUSSCD := 1.0;
    END_IF;
ELSE
    GAUSSCD := (ERF(X := (X - U) / (SI * 1.414213562)) + 1.0) * 0.5;
END_IF;
END_FUNCTION

FUNCTION GCD : INT
VAR_INPUT
    A : DINT;
    B : DINT;
END_VAR
VAR
    Left : DINT;
    Right : DINT;
    Temp : DINT;
END_VAR
Left := ABS(A);
Right := ABS(B);
WHILE Right <> 0 DO
    Temp := Left MOD Right;
    Left := Right;
    Right := Temp;
END_WHILE;
GCD := DINT_TO_INT(Left);
END_FUNCTION

FUNCTION GDF : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    GDF := 0.0;
ELSIF X > 15.0 THEN
    GDF := MATH.PI05;
ELSIF X < -15.0 THEN
    GDF := -MATH.PI05;
ELSE
    GDF := ATAN(EXP(X)) * 2.0 - MATH.PI05;
END_IF;
END_FUNCTION

FUNCTION GOLD : REAL
VAR_INPUT
    X : REAL;
END_VAR
GOLD := (X + SQRT(X * X + 4.0)) * 0.5;
END_FUNCTION

FUNCTION HYPOT : REAL
VAR_INPUT
    X : REAL;
    Y : REAL;
END_VAR
HYPOT := SQRT(X * X + Y * Y);
END_FUNCTION

FUNCTION INC : INT
VAR_INPUT
    X : INT;
    D : INT;
    M : INT;
END_VAR
INC := (X + D + M + 1) MOD (M + 1);
END_FUNCTION

FUNCTION INC1 : INT
VAR_INPUT
    X : INT;
    N : INT;
END_VAR
IF X >= N - 1 THEN
    INC1 := 0;
ELSE
    INC1 := X + 1;
END_IF;
END_FUNCTION

FUNCTION INC2 : INT
VAR_INPUT
    X : INT;
    D : INT;
    L : INT;
    U : INT;
END_VAR
VAR
    Span : INT;
END_VAR
Span := U - L + 1;
INC2 := (X + D - L + Span) MOD Span + L;
END_FUNCTION

FUNCTION INV : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X <> 0.0 THEN
    INV := 1.0 / X;
ELSE
    INV := 0.0;
END_IF;
END_FUNCTION

FUNCTION LAMBERT_W : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    W : REAL;
    NextW : REAL;
    We : REAL;
    W1e : REAL;
    Ewx : REAL;
    I : INT;
END_VAR
IF X < -0.367879441171442 THEN
    LAMBERT_W := -1000.0;
ELSIF X = 0.0 THEN
    LAMBERT_W := 0.0;
ELSE
    IF X <= 500.0 THEN
        W := LN(X + 1.0);
        W := 0.665 * (1.0 + 0.0195 * W) * W + 0.04;
    ELSE
        W := LN(X - 4.0) - (1.0 - 1.0 / LN(X)) * LN(LN(X));
    END_IF;
    FOR I := 0 TO 5 DO
        Ewx := EXP(W);
        We := W * Ewx - X;
        W1e := (W + 1.0) * Ewx;
        NextW := W - (We / (W1e - (W + 2.0) * We / (2.0 * W + 2.0)));
        IF ABS(NextW - W) < 1.0E-6 THEN
            W := NextW;
            EXIT;
        END_IF;
        W := NextW;
    END_FOR;
    LAMBERT_W := W;
END_IF;
END_FUNCTION

FUNCTION LANGEVIN : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    LANGEVIN := 0.0;
ELSE
    LANGEVIN := COTH(X := X) - 1.0 / X;
END_IF;
END_FUNCTION

FUNCTION MAX3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
MAX3 := MAX(MAX(IN1, IN2), IN3);
END_FUNCTION

FUNCTION MID3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
VAR
    A : REAL;
    B : REAL;
END_VAR
A := IN1;
B := IN2;
IF A > B THEN
    MID3 := A;
    A := B;
    B := MID3;
END_IF;
IF B > IN3 THEN
    B := IN3;
END_IF;
MID3 := SEL(A > B, B, A);
END_FUNCTION

FUNCTION MIN3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
MIN3 := MIN(MIN(IN1, IN2), IN3);
END_FUNCTION

FUNCTION MODR : REAL
VAR_INPUT
    IN : REAL;
    DIVI : REAL;
END_VAR
VAR
    QuotientFloor : DINT;
END_VAR
IF DIVI = 0.0 THEN
    MODR := 0.0;
ELSE
    QuotientFloor := FLOOR2(X := IN / DIVI);
    MODR := IN - DINT_TO_REAL(QuotientFloor) * DIVI;
END_IF;
END_FUNCTION

FUNCTION MUL_ADD : REAL
VAR_INPUT
    X : REAL;
    K : REAL;
    O : REAL;
END_VAR
MUL_ADD := X * K + O;
END_FUNCTION

FUNCTION NEGX : REAL
VAR_INPUT
    X : REAL;
END_VAR
NEGX := -X;
END_FUNCTION

FUNCTION RAD : REAL
VAR_INPUT
    DEG : REAL;
END_VAR
RAD := MODR(IN := 0.0174532925199433 * DEG, DIVI := MATH.PI2);
END_FUNCTION

FUNCTION RDM : REAL
VAR_INPUT
    LAST : REAL;
END_VAR
VAR
    Tn : DWORD;
    Tc : INT;
    Seed : REAL;
END_VAR
Tn := T_PLC_MS();
Tc := BIT_COUNT(IN := Tn);
Tn := ROL(Tn OR DWORD#16#80000001, Tc MOD 32);
Seed := LIMIT(0.0, LAST, 1.0);
RDM := FRACT(X := ABS(SIN(DWORD_TO_REAL(Tn) * 0.0001 + Seed * MATH.PI2)) * 10000.0);
END_FUNCTION

FUNCTION RDM2 : INT
VAR_INPUT
    LAST : INT;
    LOW : INT;
    HIGH : INT;
END_VAR
VAR
    Span : INT;
END_VAR
Span := HIGH - LOW + 1;
RDM2 := DINT_TO_INT(D_TRUNC(X := RDM(LAST := FRACT(X := INT_TO_REAL(LAST) * MATH.PI)) * INT_TO_REAL(Span))) + LOW;
END_FUNCTION

FUNCTION RDMDW : DWORD
VAR_INPUT
    LAST : DWORD;
END_VAR
VAR
    RX : REAL;
    M : REAL;
END_VAR
M := INT_TO_REAL(BIT_COUNT(IN := LAST));
RX := RDM(LAST := FRACT(X := M * MATH.PI));
RDMDW := SHL(REAL_TO_DWORD(RX * 65535.0), 16);
RX := RDM(LAST := FRACT(X := M * MATH.E));
RDMDW := RDMDW OR (REAL_TO_DWORD(RX * 65535.0) AND DWORD#16#0000FFFF);
END_FUNCTION

FUNCTION REAL_TO_FRAC : FRACTION
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
VAR
    Result : FRACTION;
    Temp : DINT;
    IsNegative : BOOL;
    WorkX : REAL;
    Rounded : DINT;
    IntegerPart : REAL;
    Numerator : DINT := 1;
    Denominator : DINT := 0;
    NumeratorOld : DINT := 0;
    DenominatorOld : DINT := 1;
END_VAR
WorkX := X;
IF WorkX < 0.0 THEN
    IsNegative := TRUE;
    WorkX := ABS(WorkX);
END_IF;
REPEAT
    Rounded := REAL_TO_DINT(WorkX);
    Temp := Numerator * Rounded + NumeratorOld;
    NumeratorOld := Numerator;
    Numerator := Temp;
    Temp := Denominator * Rounded + DenominatorOld;
    DenominatorOld := Denominator;
    Denominator := Temp;
    IntegerPart := DINT_TO_REAL(Rounded);
    IF WorkX = IntegerPart THEN
        IF ABS(Denominator) <= N THEN
            NumeratorOld := Numerator;
            DenominatorOld := Denominator;
        END_IF;
        EXIT;
    ELSE
        WorkX := 1.0 / (WorkX - IntegerPart);
    END_IF;
UNTIL ABS(Denominator) > N
END_REPEAT;
IF IsNegative THEN
    Result.NUMERATOR := -ABS(DINT_TO_INT(NumeratorOld));
ELSE
    Result.NUMERATOR := ABS(DINT_TO_INT(NumeratorOld));
END_IF;
Result.DENOMINATOR := ABS(DINT_TO_INT(DenominatorOld));
REAL_TO_FRAC := Result;
END_FUNCTION

FUNCTION RND : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
VAR
    M : REAL;
END_VAR
IF X = 0.0 THEN
    RND := 0.0;
ELSE
    M := EXPN(X := 10.0, N := N - CEIL(X := LOG(ABS(X))));
    RND := DINT_TO_REAL(D_TRUNC(X := X * M)) / M;
END_IF;
END_FUNCTION

FUNCTION ROUND : REAL
VAR_INPUT
    IN : REAL;
    N : INT;
END_VAR
VAR
    Scale : REAL;
    Rounded : DINT;
END_VAR
Scale := EXPN(X := 10.0, N := LIMIT(0, N, 8));
IF IN >= 0.0 THEN
    Rounded := D_TRUNC(X := IN * Scale + 0.5);
ELSE
    Rounded := D_TRUNC(X := IN * Scale - 0.5);
END_IF;
ROUND := DINT_TO_REAL(Rounded) / Scale;
END_FUNCTION

FUNCTION SGN : INT
VAR_INPUT
    X : REAL;
END_VAR
IF X > 0.0 THEN
    SGN := 1;
ELSIF X < 0.0 THEN
    SGN := -1;
ELSE
    SGN := 0;
END_IF;
END_FUNCTION

FUNCTION SIGMOID : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    SIGMOID := 1.0;
ELSIF X < -85.0 THEN
    SIGMOID := 0.0;
ELSE
    SIGMOID := 1.0 / (1.0 + EXP(-X));
END_IF;
END_FUNCTION

FUNCTION SIGN_I : BOOL
VAR_INPUT
    IN : DINT;
END_VAR
SIGN_I := IN < 0;
END_FUNCTION

FUNCTION SIGN_R : BOOL
VAR_INPUT
    IN : REAL;
END_VAR
SIGN_R := IN < 0.0;
END_FUNCTION

FUNCTION SINC : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    SINC := 1.0;
ELSE
    SINC := SIN(X) / X;
END_IF;
END_FUNCTION

FUNCTION SINH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF ABS(X) < 2.0E-3 THEN
    SINH := X;
ELSE
    SINH := (EXP(X) - EXP(-X)) * 0.5;
END_IF;
END_FUNCTION

FUNCTION SQRTN : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
IF N > 0 THEN
    IF X = 0.0 THEN
        SQRTN := 0.0;
    ELSIF X > 0.0 THEN
        SQRTN := EXP(LN(X) / INT_TO_REAL(N));
    ELSE
        SQRTN := 0.0;
    END_IF;
ELSE
    SQRTN := 0.0;
END_IF;
END_FUNCTION

FUNCTION TANC : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    TANC := 1.0;
ELSE
    TANC := TAN(X) / X;
END_IF;
END_FUNCTION

FUNCTION TANH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    TANH := 1.0;
ELSIF X < -20.0 THEN
    TANH := -1.0;
ELSE
    TANH := 1.0 - 2.0 / (EXP(2.0 * X) + 1.0);
END_IF;
END_FUNCTION

FUNCTION WINDOW : BOOL
VAR_INPUT
    LOW : REAL;
    IN : REAL;
    HIGH : REAL;
END_VAR
WINDOW := IN < HIGH AND IN > LOW;
END_FUNCTION

FUNCTION WINDOW2 : BOOL
VAR_INPUT
    LOW : REAL;
    IN : REAL;
    HIGH : REAL;
END_VAR
WINDOW2 := IN >= LOW AND IN <= HIGH;
END_FUNCTION

(* OSCAT BASIC 3.33 Chapter 6 Arrays helpers. *)

FUNCTION _ARRAY_ABS : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := ABS(PT^[I]);
END_FOR;
_ARRAY_ABS := TRUE;
END_FUNCTION

FUNCTION _ARRAY_ADD : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
    X : REAL;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := PT^[I] + X;
END_FOR;
_ARRAY_ADD := TRUE;
END_FUNCTION

FUNCTION _ARRAY_INIT : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
    INIT : REAL;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := INIT;
END_FOR;
_ARRAY_INIT := TRUE;
END_FUNCTION

FUNCTION _ARRAY_MEDIAN : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    Mid : INT;
END_VAR
_ARRAY_SORT(PT := PT, SIZE := SIZE);
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    _ARRAY_MEDIAN := 0.0;
ELSIF (Count MOD 2) = 1 THEN
    Mid := Count / 2;
    _ARRAY_MEDIAN := PT^[Mid];
ELSE
    Mid := Count / 2;
    _ARRAY_MEDIAN := (PT^[Mid - 1] + PT^[Mid]) * 0.5;
END_IF;
END_FUNCTION

FUNCTION _ARRAY_MUL : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
    X : REAL;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := PT^[I] * X;
END_FOR;
_ARRAY_MUL := TRUE;
END_FUNCTION

FUNCTION _ARRAY_SHUFFLE : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Temp : REAL;
    Pos : INT;
    I : INT;
    Stop : INT;
END_VAR
Stop := UINT_TO_INT(SIZE) / 4 - 1;
FOR I := 0 TO Stop DO
    Pos := RDM2(LAST := I + Pos, LOW := I, HIGH := Stop);
    Temp := PT^[I];
    PT^[I] := PT^[Pos];
    PT^[Pos] := Temp;
END_FOR;
_ARRAY_SHUFFLE := TRUE;
END_FUNCTION

FUNCTION _ARRAY_SORT : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
    J : INT;
    Value : REAL;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 1 TO Count - 1 DO
    Value := PT^[I];
    J := I - 1;
    WHILE J >= 0 DO
        IF PT^[J] > Value THEN
            PT^[J + 1] := PT^[J];
            J := J - 1;
        ELSE
            EXIT;
        END_IF;
    END_WHILE;
    PT^[J + 1] := Value;
END_FOR;
_ARRAY_SORT := TRUE;
END_FUNCTION

FUNCTION ARRAY_AVG : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_AVG := 0.0;
ELSE
    ARRAY_AVG := PT^[0];
    FOR I := 1 TO Count - 1 DO
        ARRAY_AVG := ARRAY_AVG + PT^[I];
    END_FOR;
    ARRAY_AVG := ARRAY_AVG / INT_TO_REAL(Count);
END_IF;
END_FUNCTION

FUNCTION ARRAY_GAV : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
ARRAY_GAV := 1.0;
FOR I := 0 TO Count - 1 DO
    IF PT^[I] > 0.0 THEN
        ARRAY_GAV := ARRAY_GAV * PT^[I];
    ELSE
        ARRAY_GAV := 0.0;
        EXIT;
    END_IF;
END_FOR;
IF ARRAY_GAV > 0.0 THEN
    ARRAY_GAV := SQRTN(X := ARRAY_GAV, N := Count);
END_IF;
END_FUNCTION

FUNCTION ARRAY_HAV : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    IF PT^[I] <> 0.0 THEN
        ARRAY_HAV := ARRAY_HAV + 1.0 / PT^[I];
    ELSE
        ARRAY_HAV := 0.0;
        EXIT;
    END_IF;
END_FOR;
IF ARRAY_HAV <> 0.0 THEN
    ARRAY_HAV := INT_TO_REAL(Count) / ARRAY_HAV;
END_IF;
END_FUNCTION

FUNCTION ARRAY_MAX : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_MAX := 0.0;
ELSE
    ARRAY_MAX := PT^[0];
    FOR I := 1 TO Count - 1 DO
        IF PT^[I] > ARRAY_MAX THEN
            ARRAY_MAX := PT^[I];
        END_IF;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION ARRAY_MIN : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_MIN := 0.0;
ELSE
    ARRAY_MIN := PT^[0];
    FOR I := 1 TO Count - 1 DO
        IF PT^[I] < ARRAY_MIN THEN
            ARRAY_MIN := PT^[I];
        END_IF;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION ARRAY_SDV : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
ARRAY_SDV := SQRT(ARRAY_VAR(PT := PT, SIZE := SIZE));
END_FUNCTION

FUNCTION ARRAY_SPR : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
ARRAY_SPR := ARRAY_MAX(PT := PT, SIZE := SIZE) - ARRAY_MIN(PT := PT, SIZE := SIZE);
END_FUNCTION

FUNCTION ARRAY_SUM : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_SUM := 0.0;
ELSE
    ARRAY_SUM := PT^[0];
    FOR I := 1 TO Count - 1 DO
        ARRAY_SUM := ARRAY_SUM + PT^[I];
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION ARRAY_TREND : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    Stop : INT;
    Half : INT;
    StartSecond : INT;
    I : INT;
    Acc : REAL;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_TREND := 0.0;
ELSE
    Stop := Count - 1;
    Half := Stop / 2;
    FOR I := 0 TO Half DO
        Acc := Acc - PT^[I];
    END_FOR;
    IF (Stop MOD 2) = 0 THEN
        StartSecond := Half;
    ELSE
        StartSecond := Half + 1;
    END_IF;
    FOR I := StartSecond TO Stop DO
        Acc := Acc + PT^[I];
    END_FOR;
    ARRAY_TREND := Acc / INT_TO_REAL(Half + 1);
END_IF;
END_FUNCTION

FUNCTION ARRAY_VAR : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    Avg : REAL;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 1 THEN
    ARRAY_VAR := 0.0;
ELSE
    Avg := ARRAY_AVG(PT := PT, SIZE := SIZE);
    FOR I := 0 TO Count - 1 DO
        ARRAY_VAR := ARRAY_VAR + (PT^[I] - Avg) * (PT^[I] - Avg);
    END_FOR;
    ARRAY_VAR := ARRAY_VAR / INT_TO_REAL(Count - 1);
END_IF;
END_FUNCTION

FUNCTION IS_SORTED : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 2 DO
    IF PT^[I] > PT^[I + 1] THEN
        IS_SORTED := FALSE;
        EXIT;
    END_IF;
END_FOR;
IF Count > 0 THEN
    IS_SORTED := TRUE;
END_IF;
END_FUNCTION

(* OSCAT BASIC 3.33 Chapter 7 complex mathematics helpers. *)

FUNCTION CABS : REAL
VAR_INPUT
    X : COMPLEX;
END_VAR
CABS := HYPOT(X := X.RE, Y := X.IM);
END_FUNCTION

FUNCTION CACOS : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
    Result : COMPLEX;
END_VAR
Y := CACOSH(X := X);
Result.RE := Y.IM;
Result.IM := -Y.RE;
CACOS := Result;
END_FUNCTION

FUNCTION CACOSH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
END_VAR
Y.RE := (X.RE - X.IM) * (X.RE + X.IM) - REAL#1.0;
Y.IM := REAL#2.0 * X.RE * X.IM;
Y := CSQRT(X := Y);
Y.RE := Y.RE + X.RE;
Y.IM := Y.IM + X.IM;
CACOSH := CLOG(X := Y);
END_FUNCTION

FUNCTION CADD : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE + Y.RE;
Result.IM := X.IM + Y.IM;
CADD := Result;
END_FUNCTION

FUNCTION CARG : REAL
VAR_INPUT
    X : COMPLEX;
END_VAR
CARG := ATAN2(Y := X.IM, X := X.RE);
END_FUNCTION

FUNCTION CASIN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
    Result : COMPLEX;
END_VAR
Y.RE := -X.IM;
Y.IM := X.RE;
Y := CASINH(X := Y);
Result.RE := Y.IM;
Result.IM := -Y.RE;
CASIN := Result;
END_FUNCTION

FUNCTION CASINH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
END_VAR
Y.RE := (X.RE - X.IM) * (X.RE + X.IM) + REAL#1.0;
Y.IM := REAL#2.0 * X.RE * X.IM;
Y := CSQRT(X := Y);
Y.RE := Y.RE + X.RE;
Y.IM := Y.IM + X.IM;
CASINH := CLOG(X := Y);
END_FUNCTION

FUNCTION CATAN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    RealSquared : REAL;
    Numerator : REAL;
    Denominator : REAL;
    Result : COMPLEX;
END_VAR
RealSquared := X.RE * X.RE;
Denominator := REAL#1.0 - RealSquared - X.IM * X.IM;
Result.RE := REAL#0.5 * ATAN(REAL#2.0 * X.RE / Denominator);
Numerator := X.IM + REAL#1.0;
Numerator := RealSquared + Numerator * Numerator;
Denominator := X.IM - REAL#1.0;
Denominator := RealSquared + Denominator * Denominator;
Result.IM := REAL#0.25 * (LN(Numerator) - LN(Denominator));
CATAN := Result;
END_FUNCTION

FUNCTION CATANH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    ImagSquared : REAL;
    Numerator : REAL;
    Denominator : REAL;
    Result : COMPLEX;
END_VAR
ImagSquared := X.IM * X.IM;
Numerator := REAL#1.0 + X.RE;
Numerator := ImagSquared + Numerator * Numerator;
Denominator := REAL#1.0 - X.RE;
Denominator := ImagSquared + Denominator * Denominator;
Result.RE := REAL#0.25 * (LN(Numerator) - LN(Denominator));
Denominator := REAL#1.0 - X.RE * X.RE - ImagSquared;
Result.IM := REAL#0.5 * ATAN(REAL#2.0 * X.IM / Denominator);
CATANH := Result;
END_FUNCTION

FUNCTION CCON : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE;
Result.IM := -X.IM;
CCON := Result;
END_FUNCTION

FUNCTION CCOS : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result := CCOSH(X := CSET(RE := -X.IM, IM := X.RE));
CCOS := Result;
END_FUNCTION

FUNCTION CCOSH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := COSH(X := X.RE) * COS(X.IM);
Result.IM := SINH(X := X.RE) * SIN(X.IM);
CCOSH := Result;
END_FUNCTION

FUNCTION CDIV : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := Y.RE * Y.RE + Y.IM * Y.IM;
Result.RE := (X.RE * Y.RE + X.IM * Y.IM) / Temp;
Result.IM := (X.IM * Y.RE - X.RE * Y.IM) / Temp;
CDIV := Result;
END_FUNCTION

FUNCTION CEXP : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := EXP(X.RE);
Result.RE := Temp * COS(X.IM);
Result.IM := Temp * SIN(X.IM);
CEXP := Result;
END_FUNCTION

FUNCTION CINV : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := X.RE * X.RE + X.IM * X.IM;
Result.RE := X.RE / Temp;
Result.IM := -X.IM / Temp;
CINV := Result;
END_FUNCTION

FUNCTION CLOG : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := LN(HYPOT(X := X.RE, Y := X.IM));
Result.IM := ATAN2(Y := X.IM, X := X.RE);
CLOG := Result;
END_FUNCTION

FUNCTION CMUL : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE * Y.RE - X.IM * Y.IM;
Result.IM := X.RE * Y.IM + X.IM * Y.RE;
CMUL := Result;
END_FUNCTION

FUNCTION CPOL : COMPLEX
VAR_INPUT
    L : REAL;
    A : REAL;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := L * COS(A);
Result.IM := L * SIN(A);
CPOL := Result;
END_FUNCTION

FUNCTION CPOW : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result := CEXP(X := CMUL(X := Y, Y := CLOG(X := X)));
CPOW := Result;
END_FUNCTION

FUNCTION CSET : COMPLEX
VAR_INPUT
    RE : REAL;
    IM : REAL;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := RE;
Result.IM := IM;
CSET := Result;
END_FUNCTION

FUNCTION CSIN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := COSH(X := X.IM) * SIN(X.RE);
Result.IM := SINH(X := X.IM) * COS(X.RE);
CSIN := Result;
END_FUNCTION

FUNCTION CSINH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := SINH(X := X.RE) * COS(X.IM);
Result.IM := COSH(X := X.RE) * SIN(X.IM);
CSINH := Result;
END_FUNCTION

FUNCTION CSQRT : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := HYPOT(X := X.RE, Y := X.IM);
Result.RE := SQRT(REAL#0.5 * (Temp + X.RE));
Result.IM := INT_TO_REAL(SGN(X := X.IM)) * SQRT(REAL#0.5 * (Temp - X.RE));
CSQRT := Result;
END_FUNCTION

FUNCTION CSUB : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE - Y.RE;
Result.IM := X.IM - Y.IM;
CSUB := Result;
END_FUNCTION

FUNCTION CTAN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Xi2 : REAL;
    Xr2 : REAL;
    Result : COMPLEX;
END_VAR
Xi2 := REAL#2.0 * X.IM;
Xr2 := REAL#2.0 * X.RE;
Temp := REAL#1.0 / (COS(Xr2) + COSH(X := Xi2));
Result.RE := Temp * SIN(Xr2);
Result.IM := Temp * SINH(X := Xi2);
CTAN := Result;
END_FUNCTION

FUNCTION CTANH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Xi2 : REAL;
    Xr2 : REAL;
    Result : COMPLEX;
END_VAR
Xi2 := REAL#2.0 * X.IM;
Xr2 := REAL#2.0 * X.RE;
Temp := REAL#1.0 / (COSH(X := Xr2) + COS(Xi2));
Result.RE := Temp * SINH(X := Xr2);
Result.IM := Temp * SIN(Xi2);
CTANH := Result;
END_FUNCTION

(* OSCAT BASIC 3.33 arithmetic helpers with REAL2 double-precision tuples. *)

FUNCTION R2_ABS : REAL2
VAR_INPUT
    X : REAL2;
END_VAR
VAR
    Result : REAL2;
END_VAR

IF X.RX >= REAL#0.0 THEN
    Result.RX := X.RX;
    Result.R1 := X.R1;
ELSE
    Result.RX := -X.RX;
    Result.R1 := -X.R1;
END_IF;
R2_ABS := Result;
END_FUNCTION

FUNCTION R2_ADD : REAL2
VAR_INPUT
    X : REAL2;
    Y : REAL;
END_VAR
VAR
    Temp : REAL;
    Result : REAL2;
END_VAR

Temp := X.RX;
Result.RX := Y + X.R1 + X.RX;
Result.R1 := Temp - Result.RX + Y + X.R1;
R2_ADD := Result;
END_FUNCTION

FUNCTION R2_ADD2 : REAL2
VAR_INPUT
    X : REAL2;
    Y : REAL2;
END_VAR
VAR
    Result : REAL2;
END_VAR

Result.R1 := X.R1 + Y.R1;
Result.RX := X.RX + Y.RX;
R2_ADD2 := Result;
END_FUNCTION

FUNCTION R2_MUL : REAL2
VAR_INPUT
    X : REAL2;
    Y : REAL;
END_VAR
VAR
    Result : REAL2;
END_VAR

Result.RX := X.RX * Y;
Result.R1 := X.R1 * Y;
R2_MUL := Result;
END_FUNCTION

FUNCTION R2_SET : REAL2
VAR_INPUT
    X : REAL;
END_VAR
VAR
    Result : REAL2;
END_VAR

Result.RX := X;
Result.R1 := REAL#0.0;
R2_SET := Result;
END_FUNCTION

(* OSCAT BASIC 3.33 arithmetic function helpers. *)

FUNCTION F_LIN : REAL
VAR_INPUT
    X : REAL;
    A : REAL;
    B : REAL;
END_VAR
F_LIN := A * X + B;
END_FUNCTION

FUNCTION F_LIN2 : REAL
VAR_INPUT
    X : REAL;
    X1 : REAL;
    Y1 : REAL;
    X2 : REAL;
    Y2 : REAL;
END_VAR
F_LIN2 := (Y2 - Y1) / (X2 - X1) * (X - X1) + Y1;
END_FUNCTION

FUNCTION F_POLY : REAL
VAR_INPUT
    X : REAL;
    C : ARRAY[0..7] OF REAL;
END_VAR
F_POLY := (((((((C[7] * X + C[6]) * X + C[5]) * X + C[4]) * X + C[3]) * X + C[2]) * X + C[1]) * X + C[0]);
END_FUNCTION

FUNCTION F_POWER : REAL
VAR_INPUT
    A : REAL;
    X : REAL;
    N : REAL;
END_VAR
F_POWER := A * EXPT(X, N);
END_FUNCTION

FUNCTION F_QUAD : REAL
VAR_INPUT
    X : REAL;
    A : REAL;
    B : REAL;
    C : REAL;
END_VAR
F_QUAD := (A * X + B) * X + C;
END_FUNCTION

FUNCTION FRMP_B : BYTE
VAR_INPUT
    START : BYTE;
    DIR : BOOL;
    TD : TIME;
    TR : TIME;
END_VAR
VAR
    TdMs : DWORD;
    TrMs : DWORD;
    DeltaValue : DINT;
    StartValue : DINT;
    ResultValue : DINT;
    MaxDeltaValue : DINT;
END_VAR
IF TD < TR THEN
    TdMs := TIME_TO_DWORD(IN := TD);
    TrMs := TIME_TO_DWORD(IN := TR);
    DeltaValue := D_TRUNC(
        X := UDINT_TO_REAL(IN := DWORD_TO_UDINT(IN := TdMs)) * REAL#256.0
            / UDINT_TO_REAL(IN := DWORD_TO_UDINT(IN := TrMs))
    );
    StartValue := BYTE_TO_DINT(IN := START);
    IF DIR THEN
        MaxDeltaValue := DINT#255 - StartValue;
        IF DeltaValue > MaxDeltaValue THEN
            DeltaValue := MaxDeltaValue;
        END_IF;
        ResultValue := StartValue + DeltaValue;
    ELSE
        MaxDeltaValue := StartValue;
        IF DeltaValue > MaxDeltaValue THEN
            DeltaValue := MaxDeltaValue;
        END_IF;
        ResultValue := StartValue - DeltaValue;
    END_IF;
    FRMP_B := DINT_TO_BYTE(IN := ResultValue);
ELSE
    IF DIR THEN
        FRMP_B := BYTE#255;
    ELSE
        FRMP_B := BYTE#0;
    END_IF;
END_IF;
END_FUNCTION

FUNCTION_BLOCK FT_AVG
VAR_INPUT
    IN : REAL;
    E : BOOL := TRUE;
    N : INT := INT#32;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    AVG : REAL;
END_VAR
VAR
    BUFF : DELAY;
    I : INT;
    INIT : BOOL;
    WINDOW : INT;
END_VAR

WINDOW := LIMIT(INT#0, N, INT#32);
IF NOT INIT OR RST THEN
    FOR I := INT#1 TO WINDOW DO
        BUFF(IN := IN, N := WINDOW, RST := FALSE);
    END_FOR;
    AVG := IN;
    INIT := TRUE;
ELSIF E THEN
    BUFF(IN := IN, N := WINDOW, RST := FALSE);
    AVG := AVG + (IN - BUFF.OUT) / INT_TO_REAL(IN := WINDOW);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_MIN_MAX
VAR_INPUT
    IN : REAL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    MX : REAL;
    MN : REAL;
END_VAR
VAR
    INIT : BOOL;
END_VAR

IF RST OR NOT INIT THEN
    MN := IN;
    MX := IN;
    INIT := TRUE;
ELSIF IN < MN THEN
    MN := IN;
ELSIF IN > MX THEN
    MX := IN;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_RMP
VAR_INPUT
    RMP : BOOL := TRUE;
    IN : REAL;
    KR : REAL;
    KF : REAL;
END_VAR
VAR_OUTPUT
    OUT : REAL;
    BUSY : BOOL;
    UD : BOOL;
END_VAR
VAR
    TxMs : DINT;
    LastMs : DINT;
    DeltaMs : DINT;
    INIT : BOOL;
END_VAR

TxMs := DWORD_TO_DINT(T_PLC_MS());
IF NOT INIT THEN
    INIT := TRUE;
    LastMs := TxMs;
    OUT := IN;
END_IF;
DeltaMs := TxMs - LastMs;

IF NOT RMP THEN
    OUT := IN;
    BUSY := FALSE;
ELSIF OUT > IN THEN
    OUT := OUT - DINT_TO_REAL(DeltaMs) * REAL#0.001 * KF;
    OUT := MAX(IN, OUT);
ELSIF OUT < IN THEN
    OUT := OUT + DINT_TO_REAL(DeltaMs) * REAL#0.001 * KR;
    OUT := MIN(IN, OUT);
END_IF;

IF OUT < IN THEN
    BUSY := TRUE;
    UD := TRUE;
ELSIF OUT > IN THEN
    BUSY := TRUE;
    UD := FALSE;
ELSE
    BUSY := FALSE;
END_IF;
LastMs := TxMs;
END_FUNCTION_BLOCK

FUNCTION LINEAR_INT : REAL
VAR_INPUT
    X : REAL;
    XY : ARRAY[1..20, 0..1] OF REAL;
    PTS : INT;
END_VAR
VAR
    I : INT;
    LocalPts : INT;
END_VAR

LocalPts := MIN(PTS, INT#20);
I := INT#2;
WHILE (I < LocalPts) AND (XY[I, 0] < X) DO
    I := I + 1;
END_WHILE;
LINEAR_INT := ((XY[I, 1] - XY[I - 1, 1]) * X - XY[I, 1] * XY[I - 1, 0] + XY[I - 1, 1] * XY[I, 0]) / (XY[I, 0] - XY[I - 1, 0]);
END_FUNCTION

FUNCTION POLYNOM_INT : REAL
VAR_INPUT
    X : REAL;
    XY : ARRAY[1..5, 0..1] OF REAL;
    PTS : INT;
END_VAR
VAR
    I : INT;
    J : INT;
    K : INT;
    Stop : INT;
    LocalPts : INT;
    Work : ARRAY[1..5, 0..1] OF REAL;
END_VAR

LocalPts := MIN(PTS, INT#5);
FOR I := INT#1 TO LocalPts DO
    FOR K := INT#0 TO INT#1 DO
        Work[I, K] := XY[I, K];
    END_FOR;
END_FOR;
FOR I := INT#1 TO LocalPts DO
    Stop := I + 1;
    FOR J := LocalPts TO Stop BY -1 DO
        Work[J, 1] := (Work[J, 1] - Work[J - 1, 1]) / (Work[J, 0] - Work[J - I, 0]);
    END_FOR;
END_FOR;

POLYNOM_INT := REAL#0.0;
FOR I := LocalPts TO INT#1 BY -1 DO
    POLYNOM_INT := POLYNOM_INT * (X - Work[I, 0]) + Work[I, 1];
END_FOR;
END_FUNCTION

(* OSCAT BASIC 3.33 geometric helpers. *)

FUNCTION CIRCLE_A : REAL
VAR_INPUT
    RX : REAL;
    AX : REAL;
END_VAR

CIRCLE_A := RX * RX * REAL#8.726646E-3 * AX;
END_FUNCTION

FUNCTION CIRCLE_C : REAL
VAR_INPUT
    RX : REAL;
    AX : REAL;
END_VAR

CIRCLE_C := REAL#1.7453293E-2 * RX * AX;
END_FUNCTION

FUNCTION CIRCLE_SEG : REAL
VAR_INPUT
    RX : REAL;
    HX : REAL;
END_VAR
VAR
    Angle : REAL;
END_VAR

CIRCLE_SEG := REAL#0.0;
IF RX > REAL#0.0 THEN
    Angle := REAL#2.0 * ACOS(IN := REAL#1.0 - LIMIT(MN := REAL#0.0, IN := HX / RX, MX := REAL#2.0));
    CIRCLE_SEG := (Angle - SIN(IN := Angle)) * RX * RX * REAL#0.5;
END_IF;
END_FUNCTION

FUNCTION CONE_V : REAL
VAR_INPUT
    RX : REAL;
    HX : REAL;
END_VAR

CONE_V := REAL#1.047197551 * RX * RX * HX;
END_FUNCTION

FUNCTION ELLIPSE_A : REAL
VAR_INPUT
    R1 : REAL;
    R2 : REAL;
END_VAR

ELLIPSE_A := REAL#3.141592653589793 * R1 * R2;
END_FUNCTION

FUNCTION ELLIPSE_C : REAL
VAR_INPUT
    R1 : REAL;
    R2 : REAL;
END_VAR

ELLIPSE_C := REAL#3.141592653589793 * (REAL#3.0 * (R1 + R2) - SQRT(IN := (REAL#3.0 * R1 + R2) * (REAL#3.0 * R2 + R1)));
END_FUNCTION

FUNCTION SPHERE_V : REAL
VAR_INPUT
    RX : REAL;
END_VAR

SPHERE_V := REAL#4.188790205 * RX * RX * RX;
END_FUNCTION

FUNCTION TRIANGLE_A : REAL
VAR_INPUT
    S1 : REAL;
    A : REAL;
    S2 : REAL;
    S3 : REAL;
END_VAR

IF A = REAL#0.0 THEN
    TRIANGLE_A := SQRT(IN := (S1 + S2 + S3) * (S1 + S2 - S3) * (S2 + S3 - S1) * (S3 + S1 - S2)) * REAL#0.25;
ELSE
    TRIANGLE_A := S1 * S2 * SIN(IN := RAD(DEG := A)) * REAL#0.5;
END_IF;
END_FUNCTION

(* OSCAT BASIC 3.33 Chapter 11 vector mathematics helpers. *)

FUNCTION V3_ABS : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
V3_ABS := SQRT(A.X * A.X + A.Y * A.Y + A.Z * A.Z);
END_FUNCTION

FUNCTION V3_ADD : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.X + B.X;
Result.Y := A.Y + B.Y;
Result.Z := A.Z + B.Z;
V3_ADD := Result;
END_FUNCTION

FUNCTION V3_ANG : REAL
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    D : REAL;
END_VAR
D := V3_ABS(A := A) * V3_ABS(A := B);
IF D > REAL#0.0 THEN
    V3_ANG := ACOS(LIMIT(REAL#-1.0, V3_DPRO(A := A, B := B) / D, REAL#1.0));
END_IF;
END_FUNCTION

FUNCTION V3_DPRO : REAL
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
V3_DPRO := A.X * B.X + A.Y * B.Y + A.Z * B.Z;
END_FUNCTION

FUNCTION V3_NORM : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
    Result : VECTOR_3;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    Result := V3_SMUL(A := A, M := REAL#1.0 / LengthA);
END_IF;
V3_NORM := Result;
END_FUNCTION

FUNCTION V3_NUL : BOOL
VAR_INPUT
    A : VECTOR_3;
END_VAR
V3_NUL := A.X = REAL#0.0 AND A.Y = REAL#0.0 AND A.Z = REAL#0.0;
END_FUNCTION

FUNCTION V3_PAR : BOOL
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
V3_PAR := V3_ABS(A := V3_XPRO(A := A, B := B)) = REAL#0.0;
END_FUNCTION

FUNCTION V3_REV : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := -A.X;
Result.Y := -A.Y;
Result.Z := -A.Z;
V3_REV := Result;
END_FUNCTION

FUNCTION V3_SMUL : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    M : REAL;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.X * M;
Result.Y := A.Y * M;
Result.Z := A.Z * M;
V3_SMUL := Result;
END_FUNCTION

FUNCTION V3_SUB : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.X - B.X;
Result.Y := A.Y - B.Y;
Result.Z := A.Z - B.Z;
V3_SUB := Result;
END_FUNCTION

FUNCTION V3_XANG : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    V3_XANG := ACOS(A.X / LengthA);
END_IF;
END_FUNCTION

FUNCTION V3_XPRO : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.Y * B.Z - A.Z * B.Y;
Result.Y := A.Z * B.X - A.X * B.Z;
Result.Z := A.X * B.Y - A.Y * B.X;
V3_XPRO := Result;
END_FUNCTION

FUNCTION V3_YANG : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    V3_YANG := ACOS(A.Y / LengthA);
END_IF;
END_FUNCTION

FUNCTION V3_ZANG : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    V3_ZANG := ACOS(A.Z / LengthA);
END_IF;
END_FUNCTION

