FUNCTION_BLOCK EVENTS
VAR_INPUT
    DATE_IN : DATE;
    ENA : BOOL;
END_VAR
VAR_OUTPUT
    Y : BOOL;
    NAME : STRING[30];
END_VAR
VAR
    i : INT;
    last_active : DATE;
    size : INT := 49;
    day_in : DINT;
    cyr : INT;
    lday : DINT;
    check : HOLIDAY_DATA;
    y_int : BOOL;
    name_int : STRING[30];
END_VAR
VAR_IN_OUT
    ELIST : ARRAY[0..49] OF HOLIDAY_DATA;
END_VAR

IF last_active <> DATE_IN THEN
    last_active := DATE_IN;
    y_int := FALSE;
    name_int := '';
    day_in := DAY_OF_DATE(DATE_IN);
    cyr := YEAR_OF_DATE(DATE_IN);

    FOR i := 0 TO size DO
        check := ELIST[i];
        lday := DAY_OF_DATE(SET_DATE(cyr, check.MONTH, check.DAY));
        IF day_in >= lday AND day_in <= lday + check.USE - 1 THEN
            y_int := TRUE;
            name_int := check.NAME;
            EXIT;
        END_IF;
    END_FOR;
END_IF;

IF ENA THEN
    Y := y_int;
    NAME := name_int;
ELSE
    Y := FALSE;
    NAME := '';
END_IF;
END_FUNCTION_BLOCK

