FUNCTION CRC_GEN : DWORD
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF BYTE;
    SIZE : INT;
    PL : INT;
    PN : DWORD;
    INIT : DWORD;
    REV_IN : BOOL;
    REV_OUT : BOOL;
    XOR_OUT : DWORD;
END_VAR
VAR
    Pos : INT;
    Shift : INT;
    Dx : BYTE;
    Bits : INT;
    Poly : DWORD;
    TopSet : BOOL;
    InputBit : BOOL;
END_VAR

Shift := INT#32 - PL;
Poly := SHL(PN, Shift);
CRC_GEN := DWORD#0;

FOR Pos := INT#0 TO INT#3 DO
    IF Pos < SIZE THEN
        Dx := PT^[Pos];
    ELSE
        Dx := BYTE#0;
    END_IF;
    IF REV_IN THEN
        Dx := REVERSE(IN := Dx);
    END_IF;
    CRC_GEN := SHL(CRC_GEN, INT#8) OR BYTE_TO_DWORD(Dx);
END_FOR;
Pos := INT#4;

CRC_GEN := CRC_GEN XOR SHL(INIT, Shift);

WHILE Pos < SIZE DO
    Dx := PT^[Pos];
    IF REV_IN THEN
        Dx := REVERSE(IN := Dx);
    END_IF;
    Pos := Pos + INT#1;

    FOR Bits := INT#0 TO INT#7 DO
        TopSet := (CRC_GEN AND DWORD#16#8000_0000) <> DWORD#0;
        InputBit := (Dx AND BYTE#16#80) <> BYTE#0;
        CRC_GEN := SHL(CRC_GEN, INT#1);
        IF InputBit THEN
            CRC_GEN := CRC_GEN OR DWORD#1;
        END_IF;
        IF TopSet THEN
            CRC_GEN := CRC_GEN XOR Poly;
        END_IF;
        Dx := SHL(Dx, INT#1);
    END_FOR;
END_WHILE;

FOR Bits := INT#0 TO INT#31 DO
    TopSet := (CRC_GEN AND DWORD#16#8000_0000) <> DWORD#0;
    CRC_GEN := SHL(CRC_GEN, INT#1);
    IF TopSet THEN
        CRC_GEN := CRC_GEN XOR Poly;
    END_IF;
END_FOR;

CRC_GEN := SHR(CRC_GEN, Shift) XOR XOR_OUT;
IF REV_OUT THEN
    CRC_GEN := REFLECT(CRC_GEN, PL);
END_IF;
END_FUNCTION

FUNCTION_BLOCK MATRIX
VAR_INPUT
    X1 : BOOL;
    X2 : BOOL;
    X3 : BOOL;
    X4 : BOOL;
    X5 : BOOL;
    Release : BOOL := FALSE;
END_VAR
VAR_OUTPUT
    CODE : BYTE;
    TP : BOOL;
    Y1 : BOOL := TRUE;
    Y2 : BOOL;
    Y3 : BOOL;
    Y4 : BOOL;
END_VAR
VAR
    Line : INT;
    X : ARRAY[0..3] OF BYTE;
    L : ARRAY[0..3] OF BYTE;
    I : INT;
    Temp : BYTE;
    Found : BOOL;
END_VAR

TP := FALSE;
CODE := BYTE#0;
Temp := BYTE#0;

IF X1 THEN
    Temp := Temp OR BYTE#1;
END_IF;
IF X2 THEN
    Temp := Temp OR BYTE#2;
END_IF;
IF X3 THEN
    Temp := Temp OR BYTE#4;
END_IF;
IF X4 THEN
    Temp := Temp OR BYTE#8;
END_IF;
IF X5 THEN
    Temp := Temp OR BYTE#16;
END_IF;
X[Line] := Temp;

Found := FALSE;
FOR I := INT#0 TO INT#3 DO
    IF NOT Found AND X[I] <> L[I] THEN
        Temp := X[I] XOR L[I];
        IF (Temp AND BYTE#1) = BYTE#1 THEN
            CODE := BYTE#1;
            IF (X[I] AND BYTE#1) = BYTE#1 THEN
                CODE := CODE OR BYTE#16#80;
                L[I] := L[I] OR BYTE#1;
            ELSE
                L[I] := L[I] AND BYTE#16#FE;
            END_IF;
        ELSIF (Temp AND BYTE#2) = BYTE#2 THEN
            CODE := BYTE#2;
            IF (X[I] AND BYTE#2) = BYTE#2 THEN
                CODE := CODE OR BYTE#16#80;
                L[I] := L[I] OR BYTE#2;
            ELSE
                L[I] := L[I] AND BYTE#16#FD;
            END_IF;
        ELSIF (Temp AND BYTE#4) = BYTE#4 THEN
            CODE := BYTE#3;
            IF (X[I] AND BYTE#4) = BYTE#4 THEN
                CODE := CODE OR BYTE#16#80;
                L[I] := L[I] OR BYTE#4;
            ELSE
                L[I] := L[I] AND BYTE#16#FB;
            END_IF;
        ELSIF (Temp AND BYTE#8) = BYTE#8 THEN
            CODE := BYTE#4;
            IF (X[I] AND BYTE#8) = BYTE#8 THEN
                CODE := CODE OR BYTE#16#80;
                L[I] := L[I] OR BYTE#8;
            ELSE
                L[I] := L[I] AND BYTE#16#F7;
            END_IF;
        ELSIF (Temp AND BYTE#16) = BYTE#16 THEN
            CODE := BYTE#5;
            IF (X[I] AND BYTE#16) = BYTE#16 THEN
                CODE := CODE OR BYTE#16#80;
                L[I] := L[I] OR BYTE#16;
            ELSE
                L[I] := L[I] AND BYTE#16#EF;
            END_IF;
        END_IF;

        TP := TRUE;
        CODE := CODE OR SHL(INT_TO_BYTE(I), INT#4);
        IF NOT Release AND (CODE AND BYTE#16#80) = BYTE#0 THEN
            CODE := BYTE#0;
            TP := FALSE;
        END_IF;
        Found := TRUE;
    END_IF;
END_FOR;

Line := (Line + INT#1) MOD INT#4;
Y1 := Line = INT#0;
Y2 := Line = INT#1;
Y3 := Line = INT#2;
Y4 := Line = INT#3;
END_FUNCTION_BLOCK

FUNCTION_BLOCK PIN_CODE
VAR_INPUT
    CB : BYTE;
    E : BOOL;
    PIN : STRING[8];
END_VAR
VAR_OUTPUT
    TP : BOOL;
END_VAR
VAR
    POS : INT := INT#1;
END_VAR

TP := FALSE;
IF E THEN
    IF CB = CODE(STR := PIN, POS := POS) THEN
        POS := POS + INT#1;
        IF POS > LEN(PIN) THEN
            TP := TRUE;
            POS := INT#1;
        END_IF;
    ELSE
        POS := INT#1;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

(* OSCAT BASIC 3.33 latches, flip-flops, and shift-register helpers. *)

FUNCTION_BLOCK LTCH
