FUNCTION_BLOCK STORE_8
VAR_INPUT
    SetIn : BOOL;
    D0 : BOOL;
    D1 : BOOL;
    D2 : BOOL;
    D3 : BOOL;
    D4 : BOOL;
    D5 : BOOL;
    D6 : BOOL;
    D7 : BOOL;
    ClrIn : BOOL;
    Rst : BOOL;
END_VAR
VAR_OUTPUT
    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
    Q4 : BOOL;
    Q5 : BOOL;
    Q6 : BOOL;
    Q7 : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF Rst OR SetIn THEN
    Q0 := NOT Rst;
    Q1 := Q0;
    Q2 := Q0;
    Q3 := Q0;
    Q4 := Q0;
    Q5 := Q0;
    Q6 := Q0;
    Q7 := Q0;
ELSE
    IF D0 THEN Q0 := TRUE; END_IF;
    IF D1 THEN Q1 := TRUE; END_IF;
    IF D2 THEN Q2 := TRUE; END_IF;
    IF D3 THEN Q3 := TRUE; END_IF;
    IF D4 THEN Q4 := TRUE; END_IF;
    IF D5 THEN Q5 := TRUE; END_IF;
    IF D6 THEN Q6 := TRUE; END_IF;
    IF D7 THEN Q7 := TRUE; END_IF;

    IF ClrIn AND NOT Edge THEN
        IF Q0 THEN
            Q0 := FALSE;
        ELSIF Q1 THEN
            Q1 := FALSE;
        ELSIF Q2 THEN
            Q2 := FALSE;
        ELSIF Q3 THEN
            Q3 := FALSE;
        ELSIF Q4 THEN
            Q4 := FALSE;
        ELSIF Q5 THEN
            Q5 := FALSE;
        ELSIF Q6 THEN
            Q6 := FALSE;
        ELSE
            Q7 := FALSE;
        END_IF;
    END_IF;
    Edge := ClrIn;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK COUNT_BR
VAR_INPUT
    SetIn : BOOL;
    IN : BYTE;
    UP : BOOL;
    DN : BOOL;
    StepSize : BYTE := BYTE#1;
    MX : BYTE := BYTE#255;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    CNT : BYTE;
END_VAR
VAR
    LastUp : BOOL;
    LastDn : BOOL;
END_VAR

IF RST THEN
    CNT := BYTE#0;
ELSIF SetIn THEN
    IF IN > MX THEN
        CNT := MX;
    ELSE
        CNT := IN;
    END_IF;
ELSIF UP AND NOT LastUp THEN
    CNT := INT_TO_BYTE(IN := INC(BYTE_TO_INT(IN := CNT), BYTE_TO_INT(IN := StepSize), BYTE_TO_INT(IN := MX)));
ELSIF DN AND NOT LastDn THEN
    CNT := INT_TO_BYTE(IN := INC(BYTE_TO_INT(IN := CNT), -BYTE_TO_INT(IN := StepSize), BYTE_TO_INT(IN := MX)));
END_IF;
LastUp := UP;
LastDn := DN;
END_FUNCTION_BLOCK

FUNCTION_BLOCK COUNT_DR
VAR_INPUT
    SetIn : BOOL;
    IN : DWORD;
    UP : BOOL;
    DN : BOOL;
    StepSize : DWORD := DWORD#1;
    MX : DWORD := DWORD#16#FFFFFFFF;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    CNT : DWORD;
END_VAR
VAR
    LastUp : BOOL;
    LastDn : BOOL;
    CntValue : UDINT;
    StepValue : UDINT;
    MaxValue : UDINT;
    InputValue : UDINT;
END_VAR

CntValue := DWORD_TO_UDINT(IN := CNT);
StepValue := DWORD_TO_UDINT(IN := StepSize);
MaxValue := DWORD_TO_UDINT(IN := MX);
InputValue := DWORD_TO_UDINT(IN := IN);

IF RST THEN
    CNT := DWORD#0;
ELSIF SetIn THEN
    IF InputValue > MaxValue THEN
        CNT := MX;
    ELSE
        CNT := IN;
    END_IF;
ELSIF UP AND NOT LastUp THEN
    IF StepValue > MaxValue - CntValue THEN
        CntValue := StepValue - (MaxValue - CntValue) - UDINT#1;
    ELSE
        CntValue := CntValue + StepValue;
    END_IF;
    CNT := UDINT_TO_DWORD(IN := CntValue);
ELSIF DN AND NOT LastDn THEN
    IF StepValue > CntValue THEN
        CntValue := MaxValue - (StepValue - CntValue) + UDINT#1;
    ELSE
        CntValue := CntValue - StepValue;
    END_IF;
    CNT := UDINT_TO_DWORD(IN := CntValue);
END_IF;
LastUp := UP;
LastDn := DN;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TOGGLE
VAR_INPUT
    CLK : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF RST THEN
    Q := FALSE;
ELSIF CLK AND NOT Edge THEN
    Q := NOT Q;
END_IF;
Edge := CLK;
END_FUNCTION_BLOCK

