FUNCTION_BLOCK FF_JKE
VAR_INPUT
    SetIn : BOOL;
    J : BOOL;
    CLK : BOOL;
    K : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF RST OR SetIn THEN
    Q := NOT RST;
ELSIF CLK AND NOT Edge THEN
    IF J XOR K THEN
        Q := J;
