FUNCTION_BLOCK SEL2_OF_3
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
    TOL : REAL;
END_VAR
VAR_OUTPUT
    Y : REAL;
    W : INT;
    E : BOOL;
END_VAR
VAR
    D12 : BOOL;
    D23 : BOOL;
    D31 : BOOL;
END_VAR

D12 := ABS(IN1 - IN2) <= TOL;
D23 := ABS(IN2 - IN3) <= TOL;
D31 := ABS(IN3 - IN1) <= TOL;

IF (D12 AND D23) OR (D12 AND D31) OR (D23 AND D31) THEN
    Y := (IN1 + IN2 + IN3) * 0.333333333333;
    E := FALSE;
    W := INT#0;
ELSIF D12 THEN
    Y := (IN1 + IN2) * 0.5;
    E := FALSE;
    W := INT#3;
ELSIF D23 THEN
    Y := (IN2 + IN3) * 0.5;
    E := FALSE;
    W := INT#1;
ELSIF D31 THEN
    Y := (IN3 + IN1) * 0.5;
    E := FALSE;
    W := INT#2;
ELSE
    E := TRUE;
    W := INT#4;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SEL2_OF_3B
VAR_INPUT
    IN1 : BOOL;
    IN2 : BOOL;
    IN3 : BOOL;
    TD : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    W : BOOL;
END_VAR
VAR
    Delay : TON;
END_VAR

Q := (IN1 AND IN2) OR (IN1 AND IN3) OR (IN2 AND IN3);
Delay(IN := (IN1 XOR IN2) OR (IN1 XOR IN3) OR (IN2 XOR IN3), PT := TD);
W := Delay.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SH
VAR_INPUT
    in : REAL;
    CLK : BOOL;
END_VAR
VAR_OUTPUT
    out : REAL;
    trig : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF CLK AND NOT Edge THEN
    out := in;
    trig := TRUE;
ELSE
    trig := FALSE;
END_IF;
Edge := CLK;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SH_1
VAR_INPUT
    in : REAL;
    PT : TIME;
END_VAR
VAR_OUTPUT
    out : REAL;
    trig : BOOL;
END_VAR
VAR
    LastMs : UDINT;
    TxMs : UDINT;
END_VAR

TxMs := DWORD_TO_UDINT(T_PLC_MS());
IF TxMs - LastMs >= DWORD_TO_UDINT(TIME_TO_DWORD(PT)) THEN
    LastMs := TxMs;
    out := in;
    trig := TRUE;
ELSE
    trig := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SH_2
VAR_INPUT
    in : REAL;
    PT : TIME;
    N : INT := 16;
    disc : INT;
END_VAR
VAR_OUTPUT
    out : REAL;
    trig : BOOL;
    avg : REAL;
    high : REAL;
    low : REAL;
END_VAR
VAR
    M : INT;
    buf : ARRAY[0..15] OF REAL;
    buf2 : ARRAY[0..15] OF REAL;
    LastMs : UDINT;
    I : INT;
    StartIdx : INT;
    Temp : REAL;
    StopIdx : INT;
    TxMs : UDINT;
    D2 : INT;
END_VAR

TxMs := DWORD_TO_UDINT(T_PLC_MS());
D2 := disc / 2;

IF TxMs - LastMs >= DWORD_TO_UDINT(TIME_TO_DWORD(PT)) THEN
    LastMs := TxMs;
    trig := TRUE;
    M := LIMIT(MN := INT#1, IN := N, MX := INT#16);
    FOR I := M - 1 TO 1 BY -1 DO
        buf2[I] := buf2[I - 1];
    END_FOR;
    buf2[0] := in;
    out := in;
    buf := buf2;

    FOR StartIdx := 0 TO M - 2 DO
        FOR I := StartIdx + 1 TO M - 1 DO
            IF buf[StartIdx] > buf[I] THEN
                Temp := buf[StartIdx];
                buf[StartIdx] := buf[I];
                buf[I] := Temp;
            END_IF;
        END_FOR;
    END_FOR;

    StopIdx := M - 1 - D2;
    StartIdx := D2;
    IF NOT EVEN(IN := INT_TO_DINT(disc)) THEN
        StartIdx := StartIdx + 1;
    END_IF;
    avg := 0.0;
    FOR I := StartIdx TO StopIdx DO
        avg := avg + buf[I];
    END_FOR;
    avg := avg / INT_TO_REAL(StopIdx - StartIdx + 1);
    low := buf[StartIdx];
    high := buf[StopIdx];
ELSE
    trig := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SH_T
VAR_INPUT
    IN : REAL;
    E : BOOL;
END_VAR
VAR_OUTPUT
    OUT : REAL;
END_VAR

IF E THEN
    OUT := IN;
END_IF;
END_FUNCTION_BLOCK

FUNCTION STAIR : REAL
VAR_INPUT
    X : REAL;
    STEP_SIZE : REAL;
END_VAR

IF STEP_SIZE > 0.0 THEN
    STAIR := DINT_TO_REAL(REAL_TO_DINT(X / STEP_SIZE)) * STEP_SIZE;
ELSE
    STAIR := X;
END_IF;
END_FUNCTION

FUNCTION_BLOCK STAIR2
VAR_INPUT
    X : REAL;
    STEP_SIZE : REAL;
END_VAR
VAR_OUTPUT
    Y : REAL;
END_VAR

IF STEP_SIZE > 0.0 THEN
    IF X >= Y + STEP_SIZE OR X <= Y - STEP_SIZE THEN
        Y := FLOOR(X := X / STEP_SIZE) * STEP_SIZE;
    END_IF;
ELSE
    Y := X;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TREND
VAR_INPUT
    X : REAL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    TU : BOOL;
    TD : BOOL;
    D : REAL;
END_VAR
VAR
    LastX : REAL;
END_VAR

TU := X > LastX;
TD := X < LastX;
Q := TU OR TD;
D := X - LastX;
LastX := X;
END_FUNCTION_BLOCK

(* OSCAT BASIC 3.33 sensor helpers. *)

FUNCTION MULTI_IN : REAL
VAR_INPUT
    in_1 : REAL;
    in_2 : REAL;
    in_3 : REAL;
    default : REAL;
    in_min : REAL;
    in_max : REAL;
    mode : BYTE;
END_VAR
VAR
    count : INT;
    F1 : BOOL;
    F2 : BOOL;
    F3 : BOOL;
END_VAR
F1 := in_1 > in_min AND in_1 < in_max;
F2 := in_2 > in_min AND in_2 < in_max;
F3 := in_3 > in_min AND in_3 < in_max;

CASE mode OF
BYTE#0:
    count := 0;
    IF F1 THEN
        count := count + 1;
        MULTI_IN := in_1;
    ELSE
        MULTI_IN := 0.0;
    END_IF;
    IF F2 THEN
        count := count + 1;
        MULTI_IN := MULTI_IN + in_2;
    END_IF;
    IF F3 THEN
        count := count + 1;
        MULTI_IN := MULTI_IN + in_3;
    END_IF;
    IF count = 0 THEN
        MULTI_IN := default;
    ELSE
        MULTI_IN := MULTI_IN / DINT_TO_REAL(INT_TO_DINT(count));
    END_IF;
BYTE#1:
    MULTI_IN := SEL(G := F1, IN0 := default, IN1 := in_1);
BYTE#2:
    MULTI_IN := SEL(G := F2, IN0 := default, IN1 := in_2);
BYTE#3:
    MULTI_IN := SEL(G := F3, IN0 := default, IN1 := in_3);
BYTE#4:
    MULTI_IN := default;
BYTE#5:
    MULTI_IN := SEL(G := F1, IN0 := in_max, IN1 := in_1);
    IF F2 AND in_2 < MULTI_IN THEN
        MULTI_IN := in_2;
    END_IF;
    IF F3 AND in_3 < MULTI_IN THEN
        MULTI_IN := in_3;
    END_IF;
    IF MULTI_IN = in_max THEN
        MULTI_IN := default;
    END_IF;
BYTE#6:
    MULTI_IN := SEL(G := F1, IN0 := in_min, IN1 := in_1);
    IF F2 AND in_2 > MULTI_IN THEN
        MULTI_IN := in_2;
    END_IF;
    IF F3 AND in_3 > MULTI_IN THEN
        MULTI_IN := in_3;
    END_IF;
    IF MULTI_IN = in_min THEN
        MULTI_IN := default;
    END_IF;
BYTE#7:
    IF F1 AND F2 AND F3 THEN
        MULTI_IN := MID3(IN1 := in_1, IN2 := in_2, IN3 := in_3);
    ELSIF F1 AND F2 THEN
        MULTI_IN := MIN(IN1 := in_1, IN2 := in_2);
    ELSIF F1 AND F3 THEN
        MULTI_IN := MIN(IN1 := in_1, IN2 := in_3);
    ELSIF F2 AND F3 THEN
        MULTI_IN := MIN(IN1 := in_2, IN2 := in_3);
    ELSIF F1 THEN
        MULTI_IN := in_1;
    ELSIF F2 THEN
        MULTI_IN := in_2;
    ELSIF F3 THEN
        MULTI_IN := in_3;
    ELSE
        MULTI_IN := default;
    END_IF;
ELSE
    MULTI_IN := 0.0;
END_CASE;
END_FUNCTION

FUNCTION RES_NI : REAL
VAR_INPUT
    T : REAL;
    R0 : REAL;
END_VAR
VAR CONSTANT
    A : REAL := 0.5485;
    B : REAL := 0.665E-3;
    C : REAL := 2.805E-9;
END_VAR
VAR
    T2 : REAL;
END_VAR
T2 := T * T;
RES_NI := R0 + A * T + B * T2 + C * T2 * T2;
END_FUNCTION

FUNCTION RES_NTC : REAL
VAR_INPUT
    T : REAL;
    RN : REAL;
    B : REAL;
END_VAR
RES_NTC := RN * EXP(B * (1.0 / (T + 273.15) - 0.00335401643468053));
END_FUNCTION

FUNCTION RES_PT : REAL
VAR_INPUT
    T : REAL;
    R0 : REAL;
END_VAR
VAR CONSTANT
    A : REAL := 3.90802E-3;
    B : REAL := -5.802E-7;
    C : REAL := -4.27350E-12;
END_VAR
VAR
    T2 : REAL;
END_VAR
T2 := T * T;
IF T >= 0.0 THEN
    RES_PT := R0 * (1.0 + A * T + B * T2);
ELSE
    RES_PT := R0 * (1.0 + A * T + B * T2 + C * (T - 100.0) * T2 * T);
END_IF;
END_FUNCTION

FUNCTION RES_SI : REAL
VAR_INPUT
    T : REAL;
    RS : REAL;
    TS : REAL;
END_VAR
VAR CONSTANT
    A : REAL := 7.64E-3;
    B : REAL := 1.66E-5;
END_VAR
VAR
    TX : REAL;
END_VAR
TX := T - TS;
RES_SI := RS * (1.0 + A * TX + B * TX * TX);
END_FUNCTION

FUNCTION SENSOR_INT : REAL
VAR_INPUT
    Voltage : REAL;
    Current : REAL;
    RP : REAL;
    RS : REAL;
END_VAR
VAR
    RG : REAL;
END_VAR
IF Current <> 0.0 THEN
    RG := Voltage / Current;
    SENSOR_INT := RP * (RG - RS) / (RP + RS - RG);
END_IF;
END_FUNCTION

FUNCTION TEMP_NI : REAL
VAR_INPUT
    Res : REAL;
    R0 : REAL;
END_VAR
TEMP_NI := (SQRT(0.30085225 - 2.66E-3 * (R0 - Res)) - 0.5485) * 751.8796992;
END_FUNCTION

FUNCTION TEMP_NTC : REAL
VAR_INPUT
    Res : REAL;
    RN : REAL;
    B : REAL;
END_VAR
IF Res > 0.0 THEN
    TEMP_NTC := B * 298.15 / (B + LN(Res / RN) * 298.15) - 273.15;
END_IF;
END_FUNCTION

FUNCTION TEMP_PT : REAL
VAR_INPUT
    Res : REAL;
    R0 : REAL;
END_VAR
VAR CONSTANT
    A : REAL := 3.9083E-3;
    B : REAL := -5.775E-7;
    accuracy : REAL := 0.01;
END_VAR
VAR
    StepSize : REAL := 50.0;
    X : REAL;
    Y : REAL;
    t1 : REAL;
END_VAR
X := A * R0;
Y := B * R0;
IF Res >= R0 THEN
    t1 := X * X - 4.0 * Y * (R0 - Res);
    IF t1 < 0.0 THEN
        TEMP_PT := 10000.0;
    ELSE
        TEMP_PT := (-X + SQRT(t1)) / (2.0 * Y);
    END_IF;
ELSE
    TEMP_PT := -100.0;
    WHILE StepSize > accuracy DO
        IF RES_PT(T := TEMP_PT, R0 := R0) < Res THEN
            TEMP_PT := TEMP_PT + StepSize;
        ELSE
            TEMP_PT := TEMP_PT - StepSize;
        END_IF;
        StepSize := StepSize * 0.5;
    END_WHILE;
END_IF;
END_FUNCTION

FUNCTION TEMP_SI : REAL
VAR_INPUT
    Res : REAL;
    RS : REAL;
    TS : REAL;
END_VAR
TEMP_SI := (-7.64E-3 + SQRT(Res / RS * 6.64E-5 - 0.803E-5)) * 30120.48193 + TS;
END_FUNCTION

