FUNCTION_BLOCK FT_Profile
VAR_INPUT
    K : REAL := 1.0;
    O : REAL;
    M : REAL := 1.0;
    E : BOOL;
END_VAR
VAR_INPUT CONSTANT
    value_0 : REAL;
    time_1 : TIME;
    value_1 : REAL;
    time_2 : TIME;
    value_2 : REAL;
    time_3 : TIME;
    value_3 : REAL;
    time_10 : TIME;
    value_10 : REAL;
    time_11 : TIME;
    value_11 : REAL;
    time_12 : TIME;
    value_12 : REAL;
    time_13 : TIME;
    value_13 : REAL;
END_VAR
VAR_OUTPUT
    Y : REAL;
    RUN : BOOL;
    ET : TIME;
END_VAR
VAR
    tx : DWORD;
    edge : BOOL;
    state : INT;
    ta : DWORD;
    tb : DWORD;
    t0 : DWORD;
    temp : REAL;
    va : REAL;
    vb : REAL;
    ElapsedMs : UDINT;
END_VAR

tx := T_PLC_MS();
IF E AND NOT edge THEN
    RUN := TRUE;
    ET := T#0s;
    t0 := tx;
    ta := tx;
    tb := TIME_TO_DWORD(multime(time_1, M));
    va := value_0;
    vb := value_1;
    temp := value_0;
    state := 1;
END_IF;
edge := E;
IF run THEN
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(ta);
    CASE state OF
        1:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_2, time_1), M));
                va := value_1;
                vb := value_2;
                temp := value_1;
                state := 2;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        2:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_3, time_2), M));
                va := value_2;
                vb := value_3;
                temp := value_2;
                state := 3;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        3:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_10, time_3), M));
                va := value_3;
                vb := value_10;
                temp := value_3;
                state := 4;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        4:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_11, time_10), M));
                va := value_10;
                vb := value_11;
                temp := value_10;
                IF E THEN
                    state := 5;
                ELSE
                    state := 6;
                END_IF;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        5:
            IF E THEN
                ta := tx;
            ELSE
                state := 6;
            END_IF;
        6:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_12, time_11), M));
                va := value_11;
                vb := value_12;
                temp := value_11;
                state := 7;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        7:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_13, time_12), M));
                va := value_12;
                vb := value_13;
                temp := value_12;
                state := 8;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        8:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                temp := value_13;
                run := FALSE;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
    END_CASE;
    Y := temp * K + O;
    ET := DWORD_TO_TIME(UDINT_TO_DWORD(DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(t0)));
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INC_DEC
VAR_INPUT
	CHa : BOOL;
	CHb : BOOL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	dir : BOOL;
	cnt : INT;
END_VAR
VAR
	edgea : BOOL;
	clk: BOOL;
	clka: BOOL;
	clkb: BOOL;
	edgeb: BOOL;
	axb: BOOL;
END_VAR
axb := cha XOR chb;
clka := cha XOR edgea;
edgea := cha;
clkb := chb XOR edgeb;
edgeb := chb;
clk := clka OR clkb;
IF axb AND clka THEN dir := TRUE; END_IF;
IF axb AND clkb THEN dir := FALSE; END_IF;
IF clk AND dir THEN cnt := cnt + 1; END_IF;
IF clk AND NOT dir THEN cnt := cnt -1; END_IF;
IF rst THEN cnt := 0; END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INTERLOCK
VAR_INPUT
	I1, I2 : BOOL;
	TL : TIME;
END_VAR
VAR_OUTPUT
	Q1, Q2 : BOOL;
END_VAR
VAR
	T1, T2 : TOF;
END_VAR
T1(IN := I1, PT := TL);
T2(IN := I2, PT := TL);
Q1 := I1 AND NOT t2.Q;
Q2 := I2 AND NOT t1.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INTERLOCK_4
VAR_INPUT CONSTANT
END_VAR
VAR_INPUT
    I0 : BOOL;
    I1 : BOOL;
    I2 : BOOL;
    I3 : BOOL;
    E : BOOL;
    MODE : INT;
END_VAR
VAR_OUTPUT
    OUT : BYTE;
    TP : BOOL;
END_VAR
VAR
    InValue : BYTE;
    Changed : BYTE;
    Last : BYTE;
    Old : BYTE;
    LMode : INT;
END_VAR
IF E THEN
    IF MODE <> LMode THEN
        OUT := BYTE#0;
        Last := BYTE#0;
        Old := BYTE#0;
        LMode := MODE;
    END_IF;
    InValue := BYTE#0;
    IF I0 THEN InValue := InValue OR BYTE#1; END_IF;
    IF I1 THEN InValue := InValue OR BYTE#2; END_IF;
    IF I2 THEN InValue := InValue OR BYTE#4; END_IF;
    IF I3 THEN InValue := InValue OR BYTE#8; END_IF;
    IF InValue <> Last THEN
        CASE MODE OF
            0:
                OUT := InValue;
            1:
                IF (InValue AND BYTE#8) <> BYTE#0 THEN OUT := BYTE#8;
                ELSIF (InValue AND BYTE#4) <> BYTE#0 THEN OUT := BYTE#4;
                ELSIF (InValue AND BYTE#2) <> BYTE#0 THEN OUT := BYTE#2;
                ELSE OUT := InValue;
                END_IF;
            2:
                Changed := (InValue XOR Last) AND InValue;
                IF (Changed AND BYTE#8) <> BYTE#0 THEN OUT := BYTE#8;
                ELSIF (Changed AND BYTE#4) <> BYTE#0 THEN OUT := BYTE#4;
                ELSIF (Changed AND BYTE#2) <> BYTE#0 THEN OUT := BYTE#2;
                ELSE OUT := Changed;
                END_IF;
            3:
                IF (OUT AND InValue) = BYTE#0 THEN
                    IF (InValue AND BYTE#8) <> BYTE#0 THEN OUT := BYTE#8;
                    ELSIF (InValue AND BYTE#4) <> BYTE#0 THEN OUT := BYTE#4;
                    ELSIF (InValue AND BYTE#2) <> BYTE#0 THEN OUT := BYTE#2;
                    ELSE OUT := InValue;
                    END_IF;
                END_IF;
        END_CASE;
        Last := InValue;
    END_IF;
    TP := OUT <> Old;
    Old := OUT;
ELSE
    OUT := BYTE#0;
    Last := BYTE#0;
    Old := BYTE#0;
    LMode := 0;
    TP := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION MANUAL : BOOL
VAR_INPUT
	IN : BOOL;
	FORCE_ON : BOOL;
	FORCE_OFF : BOOL;
END_VAR
MANUAL := NOT FORCE_OFF AND (IN OR FORCE_ON);
END_FUNCTION

FUNCTION_BLOCK MANUAL_1
VAR_INPUT
	IN : BOOL;
	MAN : BOOL;
	M_I : BOOL;
	SET_REQ : BOOL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	Q : BOOL;
	STATUS : BYTE;
END_VAR
VAR
	S_edge : BOOL;
	reset_edge : BOOL;
	edge: BOOL;
END_VAR
IF NOT man THEN
	Q := IN;
	STATUS := BYTE#100;
	edge := FALSE;
ELSIF NOT s_edge AND SET_REQ THEN
	Q := TRUE;
	edge := TRUE;
	status := BYTE#101;
ELSIF NOT reset_edge AND RST THEN
	Q := FALSE;
	edge := TRUE;
	status := BYTE#102;
ELSIF NOT edge THEN
	Q := M_I;
	status := BYTE#103;
END_IF;
s_edge := SET_REQ;
reset_edge := RST;
END_FUNCTION_BLOCK

FUNCTION_BLOCK MANUAL_2
VAR_INPUT
	IN : BOOL;
	ENA : BOOL;
	FORCE_ON : BOOL;
	FORCE_OFF : BOOL;
	MAN : BOOL;
END_VAR
VAR_OUTPUT
	Q : BOOL;
	STATUS : BYTE;
END_VAR
IF ena THEN
	IF NOT FORCE_ON AND NOT FORCE_OFF THEN
		Q := IN;
		STATUS := BYTE#100;
	ELSIF FORCE_ON AND NOT FORCE_OFF THEN
		Q := TRUE;
		STATUS := BYTE#101;
	ELSIF NOT FORCE_ON AND FORCE_OFF THEN
		q := FALSE;
		STATUS := BYTE#102;
	ELSE
		Q := MAN;
		STATUS := BYTE#103;
	END_IF;
ELSE
	Q := FALSE;
	STATUS := BYTE#104;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK MANUAL_4
VAR_INPUT
	I0, I1, I2, I3 : BOOL;
	MAN : BOOL;
	STP : BOOL;
	M0, M1, M2, M3 : BOOL;
END_VAR
VAR_OUTPUT
	Q0, Q1, Q2, Q3 : BOOL;
	STATUS : BYTE;
END_VAR
VAR
	edge: BOOL;
	pos : INT;
	tog: BOOL;
END_VAR
IF man THEN
	IF NOT TOG THEN
		Q0 := M0;
		Q1 := M1;
		Q2 := M2;
		Q3 := M3;
		STATUS := BYTE#101;
	END_IF;
	IF STP AND NOT edge THEN
		tog := TRUE;
		CASE pos OF
			0:	Q0 := TRUE;
				Q1 := FALSE;
				Q2 := FALSE;
				Q3 := FALSE;
				STATUS := BYTE#110;
			1:	Q0 := FALSE;
				Q1 := TRUE;
				Q2 := FALSE;
				Q3 := FALSE;
				STATUS := BYTE#111;
			2:	Q0 := FALSE;
				Q1 := FALSE;
				Q2 := TRUE;
				Q3 := FALSE;
				STATUS := BYTE#112;
			3:	Q0 := FALSE;
				Q1 := FALSE;
				Q2 := FALSE;
				Q3 := TRUE;
				STATUS := BYTE#113;
		END_CASE;
		pos := INC(pos,1,3);
	END_IF;
ELSE
	Q0 := I0;
	Q1 := I1;
	Q2 := I2;
	Q3 := I3;
	STATUS := BYTE#100;
	tog := FALSE;
	pos := 0;
END_IF;
edge := STP;
END_FUNCTION_BLOCK

FUNCTION_BLOCK PARSET
VAR_INPUT
    A0, A1 : BOOL;
END_VAR
VAR_INPUT CONSTANT
    X01, X02, X03, X04 : REAL;
    X11, X12, X13, X14 : REAL;
    X21, X22, X23, X24 : REAL;
    X31, X32, X33, X34 : REAL;
    TC : TIME;
END_VAR
VAR_OUTPUT
    P1, P2, P3, P4 : REAL;
END_VAR
VAR
    X : ARRAY[0..3,1..4] OF REAL;
    S1, S2, S3, S4 : REAL;
    tx, last : DWORD;
    start : BOOL;
    SetIndex : INT;
    LastA0 : BOOL;
