	LIMIT_HIGH : REAL;
	LIMIT_LOW : REAL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	Y : REAL;
	V : REAL;
END_VAR
VAR
	cycle_time : TC_S;
	init: BOOL;
	AUpLimited : REAL;
	ADnLimited : REAL;
	VUpMaxLimited : REAL;
	VDnMaxLimited : REAL;
END_VAR
cycle_time();
AUpLimited := MAX(0.0, A_UP);
ADnLimited := MIN(0.0, A_DN);
VUpMaxLimited := MAX(0.0, VU_MAX);
VDnMaxLimited := MIN(0.0, VD_MAX);
IF rst OR NOT init THEN
	init := TRUE;
	Y := 0.0;
	V := 0.0;
ELSIF X = Y THEN
	v := 0.0;
ELSIF X > Y THEN
	v := MIN(v + AUpLimited * cycle_time.TC, VUpMaxLimited);
	v := MIN(SQRT((Y-X) * 2.0 * ADnLimited), v);
	y := LIMIT(limit_low, y + MIN(v * cycle_time.TC, X-Y), limit_high);
ELSIF X < Y THEN
	v := MAX(v + ADnLimited * cycle_time.TC, VDnMaxLimited);
	v := MAX(-SQRT((Y-X) * 2.0 * AUpLimited), v);
	y := LIMIT(limit_low, y + MAX(v * cycle_time.TC, X-Y), limit_high);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TUNE
VAR_INPUT
    SET_REQ : BOOL;
    SU, SD : BOOL;
    RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
    SS : REAL := 0.1;
    Limit_L : REAL;
    LIMIT_H : REAL := 100.0;
    RST_val : REAL;
    SET_val : REAL := 100.0;
    T1 : TIME := T#500ms;
    T2 : TIME := T#2s;
    S1 : REAL := 2.0;
    S2 : REAL := 10.0;
END_VAR
VAR_OUTPUT
    Y : REAL;
END_VAR
VAR
    tx : DWORD;
    start, start2 : DWORD;
    state : INT;
    in : BOOL;
    STEP_DELTA : REAL;
    SPEED : REAL;
    Y_start : REAL;
    Y_start2 : REAL;
    ElapsedMs : UDINT;
    T1Ms : UDINT;
    T2Ms : UDINT;
END_VAR

tx := T_PLC_MS();
T1Ms := DWORD_TO_UDINT(TIME_TO_DWORD(T1));
T2Ms := DWORD_TO_UDINT(TIME_TO_DWORD(T2));
IF rst THEN
    Y := RST_val;
    state := 0;
ELSIF SET_REQ THEN
    Y := SET_val;
    state := 0;
ELSIF state > 0 THEN
    IF state = 1 THEN
        in := su;
    ELSE
        in := sd;
    END_IF;
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(start);
    IF NOT in AND ElapsedMs <= T1Ms THEN
        Y := Y_start + STEP_DELTA;
        state := 0;
    ELSIF in AND ElapsedMs >= T2Ms THEN
        Y := Y_start2 + UDINT_TO_REAL(DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(start2)) * s2 / speed;
    ELSIF in AND ElapsedMs >= T1Ms THEN
        Y := Y_start + UDINT_TO_REAL(ElapsedMs - T1Ms) * S1 / speed;
        start2 := tx;
        Y_start2 := Y;
    ELSIF NOT in THEN
        state := 0;
    END_IF;
ELSIF su THEN
    state := 1;
    start := tx;
    STEP_DELTA := ss;
    speed := 1000.0;
    Y_start := Y;
ELSIF sd THEN
    state := 2;
    start := tx;
    STEP_DELTA := -ss;
    speed := -1000.0;
    Y_start := Y;
END_IF;
Y := LIMIT(LIMIT_L, Y, LIMIT_H);
END_FUNCTION_BLOCK

FUNCTION_BLOCK TUNE2
VAR_INPUT
    SET_REQ : BOOL;
    SU, SD : BOOL;
    FU, FD : BOOL;
    RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
    SS : REAL := 0.1;
    FS : REAL := 5.0;
    Limit_L : REAL;
    LIMIT_H : REAL := 100.0;
    RST_val : REAL;
    SET_val : REAL := 100.0;
    TR : TIME := T#500ms;
    S1 : REAL := 2.0;
    S2 : REAL := 10.0;
END_VAR
VAR_OUTPUT
    Y : REAL;
END_VAR
VAR
    tx : DWORD;
    start : DWORD;
    state : INT;
    in : BOOL;
    STEP_DELTA : REAL;
    SPEED : REAL;
    Y_start : REAL;
    ElapsedMs : UDINT;
    TRMs : UDINT;
END_VAR

tx := T_PLC_MS();
TRMs := DWORD_TO_UDINT(TIME_TO_DWORD(TR));
IF rst THEN
    Y := RST_val;
    state := 0;
ELSIF SET_REQ THEN
    Y := SET_val;
    state := 0;
ELSIF state > 0 THEN
    CASE state OF
        1 :
            in := su;
        2 :
            in := sd;
        3 :
            in := fu;
        4 :
            in := fd;
    END_CASE;
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(start);
    IF NOT in AND ElapsedMs <= TRMs THEN
        Y := Y_start + STEP_DELTA;
        state := 0;
    ELSIF in AND ElapsedMs >= TRMs THEN
        Y := Y_start + UDINT_TO_REAL(ElapsedMs - TRMs) * speed;
    ELSIF NOT in THEN
        state := 0;
    END_IF;
ELSIF su THEN
    state := 1;
    start := tx;
    STEP_DELTA := ss;
    speed := s1 * 1.0E-3;
    Y_start := Y;
ELSIF sd THEN
    state := 2;
    start := tx;
    STEP_DELTA := -ss;
    speed := -s1 * 1.0E-3;
    Y_start := Y;
ELSIF fu THEN
    state := 3;
    start := tx;
    STEP_DELTA := fs;
    speed := s2 * 1.0E-3;
    Y_start := Y;
ELSIF fd THEN
    state := 4;
    start := tx;
    STEP_DELTA := -fs;
    speed := -s2 * 1.0E-3;
    Y_start := Y;
END_IF;
Y := LIMIT(LIMIT_L, Y, LIMIT_H);
END_FUNCTION_BLOCK

FUNCTION _BUFFER_CLEAR : BOOL
VAR_IN_OUT
    PT : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    SIZE : UINT;
END_VAR
VAR
    Index : INT;
    Limit : INT;
END_VAR

_BUFFER_CLEAR := TRUE;
Limit := UINT_TO_INT(SIZE);
IF Limit > INT#0 THEN
    FOR Index := INT#0 TO Limit - INT#1 DO
        PT[Index] := BYTE#0;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION _BUFFER_INIT : BOOL
VAR_IN_OUT
    PT : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    SIZE : UINT;
    INIT : BYTE;
END_VAR
VAR
    Index : INT;
    Limit : INT;
END_VAR

_BUFFER_INIT := TRUE;
Limit := UINT_TO_INT(SIZE);
IF Limit > INT#0 THEN
    FOR Index := INT#0 TO Limit - INT#1 DO
        PT[Index] := INIT;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION _STRING_TO_BUFFER : INT
VAR_IN_OUT
    PT : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    STR : STRING[STRING_LENGTH];
    POS : INT;
    SIZE : UINT;
END_VAR
VAR
    EndPos : INT;
    Index : INT;
END_VAR

_STRING_TO_BUFFER := POS;
IF POS >= INT#0 THEN
    EndPos := MIN(POS + LEN(STR), UINT_TO_INT(SIZE));
    IF EndPos > POS THEN
        FOR Index := POS TO EndPos - INT#1 DO
            PT[Index] := CODE(STR := STR, POS := Index - POS + INT#1);
        END_FOR;
    END_IF;
    _STRING_TO_BUFFER := EndPos;
END_IF;
END_FUNCTION

FUNCTION _BUFFER_INSERT : INT
VAR_IN_OUT
    PT : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    STR : STRING[STRING_LENGTH];
    POS : INT;
    SIZE : UINT;
END_VAR
VAR
    EndPos : INT;
    Limit : INT;
    CopyLen : INT;
    Index : INT;
    WritePos : INT;
END_VAR

_BUFFER_INSERT := POS;
Limit := UINT_TO_INT(SIZE);
CopyLen := LEN(STR);
IF POS >= INT#0 AND POS < Limit AND CopyLen > INT#0 THEN
    EndPos := MIN(POS + CopyLen, Limit);
    IF EndPos < Limit THEN
        FOR Index := Limit - INT#1 TO EndPos BY -INT#1 DO
            PT[Index] := PT[Index - CopyLen];
        END_FOR;
    END_IF;
    WritePos := POS;
    WHILE WritePos < EndPos DO
        PT[WritePos] := CODE(STR := STR, POS := WritePos - POS + INT#1);
        WritePos := WritePos + INT#1;
    END_WHILE;
    _BUFFER_INSERT := EndPos;
ELSIF POS >= INT#0 THEN
    _BUFFER_INSERT := MIN(POS, Limit);
END_IF;
END_FUNCTION

FUNCTION _BUFFER_UPPERCASE : BOOL
VAR_IN_OUT
    PT : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    SIZE : INT;
END_VAR
VAR
    Index : INT;
END_VAR

_BUFFER_UPPERCASE := TRUE;
IF SIZE > INT#0 THEN
    FOR Index := INT#0 TO SIZE - INT#1 DO
        PT[Index] := TO_UPPER(IN := PT[Index]);
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION BUFFER_COMP : INT
VAR_IN_OUT
    PT1 : ARRAY[*] OF BYTE;
    PT2 : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    SIZE1 : INT;
    SIZE2 : INT;
    START : INT;
END_VAR
VAR
    I : INT;
    J : INT;
    EndPos : INT;
    Match : BOOL;
END_VAR

BUFFER_COMP := INT#-1;
IF SIZE2 > INT#0 AND SIZE2 <= SIZE1 THEN
    EndPos := SIZE1 - SIZE2;
    FOR I := START TO EndPos DO
        IF BUFFER_COMP = INT#-1 AND PT1[I] = PT2[0] THEN
            Match := TRUE;
            J := INT#1;
            WHILE J < SIZE2 DO
                IF Match AND PT2[J] <> PT1[I + J] THEN
                    Match := FALSE;
                END_IF;
                J := J + INT#1;
            END_WHILE;
            IF Match THEN
                BUFFER_COMP := I;
            END_IF;
        END_IF;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION BUFFER_SEARCH : INT
VAR_IN_OUT
    PT : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    SIZE : INT;
    STR : STRING[STRING_LENGTH];
    POS : INT;
    IGN : BOOL;
END_VAR
VAR
    I : INT;
    K : INT;
    EndPos : INT;
    Match : BOOL;
    Current : BYTE;
END_VAR

BUFFER_SEARCH := INT#-1;
IF LEN(STR) > INT#0 AND SIZE > INT#0 AND POS >= INT#0 THEN
    EndPos := MIN(SIZE - LEN(STR), SIZE - INT#1);
    FOR I := POS TO EndPos DO
        IF BUFFER_SEARCH = INT#-1 THEN
            Match := TRUE;
            K := INT#0;
            WHILE K < LEN(STR) DO
                IF IGN THEN
                    Current := TO_UPPER(IN := PT[I + K]);
                ELSE
                    Current := PT[I + K];
                END_IF;
                IF Match AND CODE(STR := STR, POS := K + INT#1) <> Current THEN
                    Match := FALSE;
                END_IF;
                K := K + INT#1;
            END_WHILE;
            IF Match THEN
                BUFFER_SEARCH := I;
            END_IF;
        END_IF;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION BUFFER_TO_STRING : STRING[STRING_LENGTH]
VAR_IN_OUT
    PT : ARRAY[*] OF BYTE;
END_VAR
VAR_INPUT
    SIZE : UINT;
    START : UINT;
    STOP : UINT;
END_VAR
VAR
    Sta : UINT;
    Stp : UINT;
    Index : UINT;
    Count : INT;
END_VAR

BUFFER_TO_STRING := '';
IF SIZE > UINT#0 THEN
    Sta := MIN(START, SIZE - UINT#1);
    Stp := MIN(STOP, SIZE - UINT#1);
    IF Stp >= Sta THEN
        Index := Sta;
        Count := INT#0;
        WHILE Index <= Stp AND Count < STRING_LENGTH DO
            BUFFER_TO_STRING := CONCAT(IN1 := BUFFER_TO_STRING, IN2 := CHR_TO_STRING(C := PT[UINT_TO_INT(Index)]));
            Index := Index + UINT#1;
            Count := Count + INT#1;
        END_WHILE;
    END_IF;
END_IF;
END_FUNCTION

FUNCTION LIST_ADD : BOOL
VAR_INPUT
    SEP : BYTE;
    INS : STRING[LIST_LENGTH];
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR
    SepText : STRING[1];
    Candidate : STRING[LIST_LENGTH];
END_VAR

SepText := CHR_TO_STRING(C := SEP);
Candidate := CONCAT(IN1 := LIST, IN2 := CONCAT(IN1 := SepText, IN2 := INS));
IF LEN(Candidate) > LIST_LENGTH THEN
    LIST_ADD := FALSE;
ELSE
    LIST := Candidate;
    LIST_ADD := TRUE;
END_IF;
END_FUNCTION

FUNCTION LIST_CLEAN : BOOL
VAR_INPUT
    SEP : BYTE;
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR
    Pos : INT;
    Current : BYTE;
    Result : STRING[LIST_LENGTH];
    LastWasSep : BOOL;
END_VAR

Result := '';
LastWasSep := FALSE;
FOR Pos := INT#1 TO LEN(LIST) DO
    Current := CODE(STR := LIST, POS := Pos);
    IF Current <> SEP OR NOT LastWasSep THEN
        Result := CONCAT(IN1 := Result, IN2 := CHR_TO_STRING(C := Current));
    END_IF;
    LastWasSep := Current = SEP;
END_FOR;

IF LEN(Result) > INT#0 AND CODE(STR := Result, POS := LEN(Result)) = SEP THEN
    Result := LEFT(IN := Result, L := LEN(Result) - INT#1);
END_IF;

LIST := Result;
LIST_CLEAN := TRUE;
END_FUNCTION

FUNCTION LIST_GET : STRING[LIST_LENGTH]
VAR_INPUT
    SEP : BYTE;
    POS : INT;
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR
    Index : INT;
    Count : INT;
    Current : BYTE;
    Done : BOOL;
END_VAR

LIST_GET := '';
Index := INT#1;
Count := INT#0;
Done := FALSE;

WHILE Index <= LEN(LIST) AND NOT Done DO
    Current := CODE(STR := LIST, POS := Index);
    IF Current = SEP THEN
        Count := Count + INT#1;
        IF Count > POS THEN
            Done := TRUE;
        END_IF;
    ELSIF Count = POS THEN
        LIST_GET := CONCAT(IN1 := LIST_GET, IN2 := CHR_TO_STRING(C := Current));
    END_IF;
    Index := Index + INT#1;
END_WHILE;
END_FUNCTION

FUNCTION LIST_INSERT : BOOL
VAR_INPUT
    SEP : BYTE;
    POS : INT;
    INS : STRING[LIST_LENGTH];
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR
    SepText : STRING[1];
    InsertText : STRING[LIST_LENGTH];
    Prefix : STRING[LIST_LENGTH];
    Suffix : STRING[LIST_LENGTH];
    InsertPos : INT;
    Index : INT;
    Count : INT;
    Done : BOOL;
END_VAR

LIST_INSERT := FALSE;
SepText := CHR_TO_STRING(C := SEP);
InsertText := CONCAT(IN1 := SepText, IN2 := INS);

IF LEN(LIST) + LEN(InsertText) <= LIST_LENGTH THEN
    InsertPos := LEN(LIST) + INT#1;
    IF POS <= INT#1 THEN
        InsertPos := INT#1;
    ELSE
        Index := INT#1;
        Count := INT#0;
        Done := FALSE;
        WHILE Index <= LEN(LIST) AND NOT Done DO
            IF CODE(STR := LIST, POS := Index) = SEP THEN
                Count := Count + INT#1;
                IF Count = POS THEN
                    InsertPos := Index;
                    Done := TRUE;
                END_IF;
            END_IF;
            Index := Index + INT#1;
        END_WHILE;
    END_IF;

    IF InsertPos > INT#1 THEN
        Prefix := LEFT(IN := LIST, L := InsertPos - INT#1);
    ELSE
        Prefix := '';
    END_IF;

    IF InsertPos <= LEN(LIST) THEN
        Suffix := MID(IN := LIST, L := LEN(LIST) - InsertPos + INT#1, P := InsertPos);
    ELSE
        Suffix := '';
    END_IF;

    LIST := CONCAT(IN1 := Prefix, IN2 := CONCAT(IN1 := InsertText, IN2 := Suffix));
    LIST_INSERT := TRUE;
END_IF;
END_FUNCTION

FUNCTION LIST_LEN : INT
VAR_INPUT
    SEP : BYTE;
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR
    Pos : INT;
END_VAR

LIST_LEN := INT#0;
FOR Pos := INT#1 TO LEN(LIST) DO
    IF CODE(STR := LIST, POS := Pos) = SEP THEN
        LIST_LEN := LIST_LEN + INT#1;
    END_IF;
END_FOR;
END_FUNCTION

FUNCTION_BLOCK LIST_NEXT
VAR_INPUT
    SEP : BYTE;
    RST : BOOL;
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR_OUTPUT
    LEL : STRING[LIST_LENGTH];
    NUL : BOOL;
END_VAR
VAR
    Pos : INT := INT#1;
    Index : INT;
    ListSize : INT;
END_VAR

IF RST THEN
    Pos := INT#1;
END_IF;

LEL := '';
ListSize := LEN(LIST);
IF Pos > ListSize OR ListSize = INT#0 THEN
    NUL := TRUE;
ELSE
    NUL := FALSE;
    Index := Pos + INT#1;
    WHILE Index <= ListSize AND CODE(STR := LIST, POS := Index) <> SEP DO
        LEL := CONCAT(IN1 := LEL, IN2 := MID(IN := LIST, L := INT#1, P := Index));
        Index := Index + INT#1;
    END_WHILE;
    Pos := Index;
END_IF;
END_FUNCTION_BLOCK

FUNCTION LIST_RETRIEVE : STRING[LIST_LENGTH]
VAR_INPUT
    SEP : BYTE;
    POS : INT;
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR
    Index : INT;
    Count : INT;
    StartPos : INT;
    EndPos : INT;
    Prefix : STRING[LIST_LENGTH];
    Suffix : STRING[LIST_LENGTH];
END_VAR

LIST_RETRIEVE := '';
StartPos := INT#0;
EndPos := LEN(LIST) + INT#1;

IF POS > INT#0 THEN
    Index := INT#1;
    Count := INT#0;
    WHILE Index <= LEN(LIST) AND EndPos = LEN(LIST) + INT#1 DO
        IF CODE(STR := LIST, POS := Index) = SEP THEN
            Count := Count + INT#1;
            IF Count = POS THEN
                StartPos := Index;
            ELSIF Count = POS + INT#1 AND StartPos > INT#0 THEN
                EndPos := Index;
            END_IF;
        END_IF;
        Index := Index + INT#1;
    END_WHILE;

    IF StartPos > INT#0 THEN
        IF EndPos > StartPos + INT#1 THEN
            LIST_RETRIEVE := MID(IN := LIST, L := EndPos - StartPos - INT#1, P := StartPos + INT#1);
        END_IF;

        IF StartPos > INT#1 THEN
            Prefix := LEFT(IN := LIST, L := StartPos - INT#1);
        ELSE
            Prefix := '';
        END_IF;

        IF EndPos <= LEN(LIST) THEN
            Suffix := MID(IN := LIST, L := LEN(LIST) - EndPos + INT#1, P := EndPos);
        ELSE
            Suffix := '';
        END_IF;

        LIST := CONCAT(IN1 := Prefix, IN2 := Suffix);
    END_IF;
END_IF;
END_FUNCTION

FUNCTION LIST_RETRIEVE_LAST : STRING[LIST_LENGTH]
VAR_INPUT
    SEP : BYTE;
END_VAR
VAR_IN_OUT
    LIST : STRING[LIST_LENGTH];
END_VAR
VAR
    Index : INT;
    LastSep : INT;
END_VAR

LIST_RETRIEVE_LAST := '';
LastSep := INT#0;

FOR Index := INT#1 TO LEN(LIST) DO
    IF CODE(STR := LIST, POS := Index) = SEP THEN
        LastSep := Index;
    END_IF;
END_FOR;

IF LastSep > INT#0 THEN
    IF LastSep < LEN(LIST) THEN
        LIST_RETRIEVE_LAST := MID(IN := LIST, L := LEN(LIST) - LastSep, P := LastSep + INT#1);
    END_IF;

    IF LastSep > INT#1 THEN
        LIST := LEFT(IN := LIST, L := LastSep - INT#1);
    ELSE
        LIST := '';
    END_IF;
END_IF;
END_FUNCTION

