PROGRAM Blinker
VAR
    Enable : BOOL := TRUE;
    Lamp : BOOL := FALSE;
    PulsePeriod : TIME := T#250ms;
    TimerEnable : BOOL := TRUE;
    BlinkTimer : TON;
END_VAR

BlinkTimer(IN := TimerEnable, PT := PulsePeriod);

IF NOT Enable THEN
    Lamp := FALSE;
    TimerEnable := FALSE;
ELSIF BlinkTimer.Q THEN
    Lamp := NOT Lamp;
    TimerEnable := FALSE;
ELSE
    TimerEnable := TRUE;
END_IF;
END_PROGRAM

PROGRAM TrafficLight
VAR
    Phase : INT := 0;
    PhasePeriod : TIME := T#500ms;
    PhaseTimerEnable : BOOL := TRUE;
    PhaseTimer : TON;
    Red : BOOL := TRUE;
    Yellow : BOOL := FALSE;
    Green : BOOL := FALSE;
END_VAR

PhaseTimer(IN := PhaseTimerEnable, PT := PhasePeriod);

CASE Phase OF
    0:
        Red := TRUE;
        Yellow := FALSE;
        Green := FALSE;
    1:
        Red := TRUE;
        Yellow := TRUE;
        Green := FALSE;
    2:
        Red := FALSE;
        Yellow := FALSE;
        Green := TRUE;
    3:
        Red := FALSE;
        Yellow := TRUE;
        Green := FALSE;
END_CASE;

IF PhaseTimer.Q THEN
    CASE Phase OF
        0:
            Phase := 1;
        1:
            Phase := 2;
        2:
            Phase := 3;
        3:
            Phase := 0;
    END_CASE;
    PhaseTimerEnable := FALSE;
ELSE
    PhaseTimerEnable := TRUE;
END_IF;
END_PROGRAM

PROGRAM TankLevel
VAR
    InletValveCmd : BOOL := FALSE;
    OutletValveCmd : BOOL := TRUE;
    LevelPercent : REAL := 45.0;
    LowSetpoint : REAL := 30.0;
    HighSetpoint : REAL := 70.0;
END_VAR

IF LevelPercent <= LowSetpoint THEN
    InletValveCmd := TRUE;
    OutletValveCmd := FALSE;
ELSIF LevelPercent >= HighSetpoint THEN
    InletValveCmd := FALSE;
    OutletValveCmd := TRUE;
END_IF;

IF InletValveCmd THEN
    LevelPercent := LevelPercent + 2.5;
END_IF;

IF OutletValveCmd THEN
    LevelPercent := LevelPercent - 1.5;
END_IF;
END_PROGRAM

PROGRAM MotorStarter
VAR
    StartPb : BOOL := FALSE;
    StopPb : BOOL := FALSE;
    OverloadTrip : BOOL := FALSE;
    MotorRun : BOOL := FALSE;
    SealInContact : BOOL := FALSE;
END_VAR

IF StopPb OR OverloadTrip THEN
    MotorRun := FALSE;
ELSIF StartPb OR SealInContact THEN
    MotorRun := TRUE;
END_IF;

SealInContact := MotorRun;
END_PROGRAM

