METHOD PUBLIC Initialize
ReadyValue := TRUE;
Limits.Low := REAL#0.0;
Limits.High := REAL#100.0;
Gains.Kp := REAL#2.0;
Gains.Tn := REAL#1.0;
Gains.Tv := REAL#0.2;
TempController.Initialize();
