VAR
    Ahu : AhuController;
    Initialized : BOOL;
    ModeRequest : INT;
    OutdoorTempRaw : INT;
    SupplyTempRaw : INT;
    SmokeClear : BOOL;
    FreezeStatClear : BOOL;
    SupplyFanHealthy : BOOL;
    HeatingValveRaw : INT;
    SupplyFanEnable : BOOL;
    FireAlarmRelay : BOOL;
