_tmpDINT:=SHR(_tmpDINT,8);
_b2:=UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT:=SHR(_tmpDINT,8);
_b1:=UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT:=SHR(_tmpDINT,8);
_b0:=UDINT_TO_BYTE(_tmpDINT MOD 256);
_tmpDINT:=SHR(_tmpDINT,8);

IF inFormat=eTcoDataFormat.LittleEndian THEN
	outByte0 := _b3;
	outByte1 := _b2;	
