	IF(_status.State.Inputs.Safety.ES_IsEmergencyStopped) THEN
		Messenger.Error('<#Emergency stop active#>');
	END_IF;
	IF( _status.State.Inputs.Safety.ST_IsStoppedDueSafety) THEN
		Messenger.Warning('<#Stopped due safety#>');
	END_IF;


END_IF;

UpdateControl();
END_FUNCTION_BLOCK

