	IF _progress = 2 THEN	
		Messenger.Debug('<#Waiting for component in  separator#>');
		_timer(IN:=inoStatus.SeparatorPresent,Pt:=inoConfig.TimeToComponentInSeparator);
		IF _timer.Q THEN
			_progress := _progress + 1;
			_timer(In:=FALSE);
		END_IF
	END_IF;

	IF _progress = 3 THEN	
		inoControl.SepareComponent:=TRUE;
		Messenger.OnCondition(NOT inoConfig.OutOfBoxSensorDisabled).Debug('<#Waiting for component out of  separator#>');
		Messenger.OnCondition(inoConfig.OutOfBoxSensorDisabled AND  inoConfig.SeparatorHasWorkPosition).Warning('<#Waiting to separator to reach work position.#>');

		_timer(IN:=inoStatus.SeparatorPresent,Pt:=inoConfig.TimeToComponentOutSeparator);
		IF  inoStatus.ComponentOutOfBox 
			AND NOT inoConfig.OutOfBoxSensorDisabled  THEN
			_progress := _progress + 1;
			_timer(In:=FALSE);
		ELSIF inoConfig.OutOfBoxSensorDisabled 
			AND inoConfig.SeparatorHasWorkPosition
			AND inoStatus.SeparatorWorkPos THEN
			_progress := _progress + 1;
			_timer(In:=FALSE); 
		ELSIF inoConfig.OutOfBoxSensorDisabled 
			AND NOT inoConfig.SeparatorHasWorkPosition
			AND _timer.Q  THEN
			_progress := _progress + 1;
			_timer(In:=FALSE); 

		ELSIF _timer.Q 
			AND NOT inoConfig.OutOfBoxSensorDisabled  THEN
			_progress := 1;
			_timer(In:=FALSE);
		END_IF
	END_IF;

	IF _progress = 4 THEN	
		_componentReady:=TRUE;
		THIS^.DoneWhen(TRUE);
	END_IF;		


    CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q );

END_IF

inoStatus.ComponentReady:=_componentReady;

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoTixonStepTask EXTENDS TcoTixonFeedingTask
VAR_IN_OUT
    inoConfig : TcoTixonStep_Config_v_1_x_x;
    inoControl : TcoTixonStep_Control_v_1_x_x;
    inoStatus : TcoTixonStep_Status_v_1_x_x;
END_VAR

VAR
    _timerIsFull : TON;

	_timerIsStucked :  TON;
END_VAR
IF Execute() THEN
	_timerIsFull(IN:=inoStatus.FillingSensor ,PT:=inoConfig.BufferFullTime);

  	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT inoStatus.ControllerInAuto THEN                                                  
			_varInfo :=__VARINFO(inoStatus.ControllerInAuto);                                                                                                 
			Messenger.Warning(_sb.Clear().Append('<#Tixon control system not in auto #>').Append(_varInfo.Symbol).ToString());
		ELSE

			IF NOT THIS^._errorMessage.Pinned THEN	
           		_progress := _progress + 1;
			END_IF;

		END_IF

	END_IF


	IF _progress = 1 THEN	
		Messenger.Debug('<#Waiting for buffer empty#>');
		_timer(IN:=NOT inoStatus.FillingSensor,Pt:=inoConfig.BufferEmptyTime);
		_timerIsStucked(in:=inoConfig.BufferStuckedOnFillingSensor<>T#0S AND inoControl.FeedingA AND inoStatus.FillingSensor AND NOT inoStatus.SeparatorPresent,Pt:=inoConfig.BufferStuckedOnFillingSensor);
		IF _timer.Q  AND inoControl.FeedingA THEN
			_progress := _progress + 1;
			_timer(In:=FALSE);
		ELSIF _timerIsStucked.Q AND  inoControl.FeedingA AND inoStatus.FillingSensor AND NOT inoStatus.SeparatorPresent THEN
			_progress := _progress + 1;
			_timer(In:=FALSE);
		END_IF
	END_IF;
	IF _progress = 2 THEN	
		inoControl.StepperValve:=FALSE;
		Messenger.Debug('<#Stepper to home#>');
		_timer(IN:=inoStatus.StepperHomePos,Pt:=inoConfig.SteperInHomeTime);
		IF  _timer.Q THEN
			_progress := _progress+1;
			_timer(In:=FALSE);
		END_IF
	END_IF;

	IF _progress = 3 THEN	
		inoControl.StepperValve:=TRUE;
		Messenger.Debug('<#Stepper to work#>');
		_timer(IN:=inoStatus.StepperWorkPos,Pt:=inoConfig.SteperInWorkTime);
		IF  _timer.Q THEN
			_progress := _progress+1;
			_timer(In:=FALSE);
		END_IF
	END_IF;

	IF _progress = 4 THEN	
		Messenger.Debug('<#Waiting for buffer full#>');
		IF _timerIsFull.Q THEN
			_progress := _progress + 1;
			_timer(In:=FALSE);
		ELSE
			_progress := 2;
			_timer(In:=FALSE);
		END_IF
	END_IF;

	IF _progress = 5 THEN	
		THIS^.DoneWhen(TRUE);
	END_IF;		


  	CallTimers(_progress>1);//empty and strat feeding


	THIS^.ThrowWhen(_errorTimer.Q );

END_IF

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

