FUNCTION_BLOCK TcoTixonBufferTask EXTENDS TcoTixonFeedingTask
VAR_IN_OUT
	inoConfig 	: TcoTixonGenericConfig;
   	inoControl 	: TcoTixonGenericControl;
	inoStatus 	: TcoTixonGenericStatus;	
END_VAR
IF Execute() THEN


    IF _progress = 0 THEN
        IF NOT __ISVALIDREF(inoControl) THEN
            _varInfo := __VARINFO(inoControl);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoConfig) THEN
            _varInfo := __VARINFO(inoConfig);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoStatus) THEN
            _varInfo := __VARINFO(inoStatus);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT inoStatus.ControllerInAuto THEN
            _varInfo := __VARINFO(inoStatus.ControllerInAuto);
            Messenger.Warning(_sb.Clear().Append('<#Tixon control system not in auto #>').Append(_varInfo.Symbol).ToString());
        ELSE
			IF NOT THIS^._errorMessage.Pinned THEN	
           		_progress := _progress + 1;
			END_IF;

        END_IF

    END_IF
  	IF _progress = 1 THEN
        Messenger.Debug('<#Waiting for buffer is Empty #>');
        _timer(IN := NOT inoStatus.FillingSensor OR (inoStatus.SeparatorHomePos AND NOT inoStatus.SeparatorPresent),
            Pt := inoConfig.BufferEmptyTime);

        IF _timer.Q THEN
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;


    END_IF;
    IF _progress = 2 THEN
        Messenger.Debug('<#Waiting for blow on #>');
        _timer(IN :=TRUE,
            Pt := inoConfig.BufferBlowStartTime);
		  inoControl.BlowAValve := inoConfig.BufferBlowActive;

        IF _timer.Q OR NOT inoConfig.BufferBlowActive THEN  
			inoControl.FeedingA:=TRUE;
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;


    END_IF;


    IF _progress = 3 THEN
        Messenger.Debug('<#Waiting for buffer is full and go idle#>');
        _timer(IN := inoStatus.FillingSensor AND InoStatus.SeparatorPresent, Pt := inoConfig.BufferIdleTime);

        IF _timer.Q THEN
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF
    END_IF;

    IF _progress = 4 THEN
        inoControl.FeedingA := FALSE;
        Messenger.Debug('<#Waiting for buffer is full and blow ending#>');
        _timer(IN := TRUE, Pt := inoConfig.BufferBlowFullTime);
        IF _timer.Q OR NOT inoConfig.BufferBlowActive THEN
            inoControl.BlowAValve := FALSE;
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;

    END_IF;

    IF _progress = 5 THEN
        THIS^.DoneWhen(TRUE);
    END_IF;

    CallTimers(_progress>1);//empty and start feeding

    THIS^.ThrowWhen(_errorTimer.Q);

END_IF

IF THIS^.Error AND NOT _errorMessage.Pinned THEN
    THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoTixonPickBufferTask EXTENDS TcoTixonFeedingTask
VAR_IN_OUT
	inoConfig 	: TcoTixonGenericPickConfig;
   	inoControl 	: TcoTixonGenericControl;
	inoStatus 	: TcoTixonGenericStatus;	
END_VAR
IF Execute() THEN


    IF _progress = 0 THEN
        IF NOT __ISVALIDREF(inoControl) THEN
            _varInfo := __VARINFO(inoControl);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoConfig) THEN
            _varInfo := __VARINFO(inoConfig);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoStatus) THEN
            _varInfo := __VARINFO(inoStatus);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT inoStatus.ControllerInAuto THEN
            _varInfo := __VARINFO(inoStatus.ControllerInAuto);
            Messenger.Warning(_sb.Clear().Append('<#Tixon control system not in auto #>').Append(_varInfo.Symbol).ToString());
        ELSE
			IF NOT THIS^._errorMessage.Pinned THEN	
           		_progress := _progress + 1;
			END_IF;

        END_IF

    END_IF
  	IF _progress = 1 THEN
        Messenger.Debug('<#Waiting for buffer is Empty #>');
        _timer(IN := NOT inoStatus.FillingSensor OR (NOT inoStatus.SeparatorPresent),
            Pt := inoConfig.BufferEmptyTime);

        IF _timer.Q THEN
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;


    END_IF;
    IF _progress = 2 THEN
        Messenger.Debug('<#Waiting for blow on #>');
        _timer(IN :=TRUE,
            Pt := inoConfig.BufferBlowStartTime);
		  inoControl.BlowAValve := inoConfig.BufferBlowActive;	
        IF _timer.Q OR NOT inoConfig.BufferBlowActive THEN  
			inoControl.FeedingA:=TRUE;
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;


    END_IF;


    IF _progress = 3 THEN
        Messenger.Debug('<#Waiting for buffer is full and go idle#>');
        _timer(IN := inoStatus.FillingSensor AND InoStatus.SeparatorPresent, Pt := inoConfig.BufferIdleTime);

        IF _timer.Q THEN
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF
    END_IF;

    IF _progress = 4 THEN
        inoControl.FeedingA := FALSE;
        Messenger.Debug('<#Waiting for buffer is full and blow ending#>');
        _timer(IN := TRUE, Pt := inoConfig.BufferBlowFullTime);
        IF _timer.Q OR NOT inoConfig.BufferBlowActive THEN
            inoControl.BlowAValve := FALSE;
            _progress := _progress + 1;
            _timer(In := FALSE);
        END_IF;

    END_IF;

    IF _progress = 5 THEN
        THIS^.DoneWhen(TRUE);
    END_IF;

    CallTimers(_progress>1);//empty and start feeding

    THIS^.ThrowWhen(_errorTimer.Q);

END_IF

IF THIS^.Error AND NOT _errorMessage.Pinned THEN
    THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoTixonHopperTask EXTENDS TcoTixonFeedingTask
VAR_IN_OUT
	inoConfig 	: TcoTixonGenericConfig;
   	inoControl 	: TcoTixonGenericControl;
	inoStatus 	: TcoTixonGenericStatus;	
END_VAR
IF Execute() THEN


  	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT inoStatus.ControllerInAuto THEN                                                  
			_varInfo :=__VARINFO(inoStatus.ControllerInAuto);                                                                                                  
			Messenger.Warning(_sb.Clear().Append('<#Tixon control system not in auto #>').Append(_varInfo.Symbol).ToString());
		ELSE

			IF NOT THIS^._errorMessage.Pinned THEN	
           		_progress := _progress + 1;
			END_IF;

		END_IF

	END_IF
	IF _progress = 1 THEN
		inoControl.Hooper:=FALSE;

		_progress := _progress + 1;
		_timer(In:=FALSE);

	END_IF;


	IF _progress = 2 THEN	
		Messenger.Debug('<#Waiting for feeder empty#>');
		_timer(IN:=NOT inoStatus.NotEmptyFeeder,Pt:=inoConfig.TimeToHopperStart);
		IF _timer.Q THEN
			_progress := _progress + 1;
			_timer(In:=FALSE);;
		END_IF
	END_IF;

	IF _progress = 3 THEN	
		inoControl.Hooper:=TRUE;
		Messenger.Debug('<#Hopper is running#>');
		_timer(IN:=inoStatus.NotEmptyFeeder,Pt:=inoConfig.TimeToHopperRun);
		IF _timer.Q THEN
			_progress := _progress+1;
			_timer(In:=FALSE);
		END_IF
	END_IF;

	IF _progress = 4 THEN	
		THIS^.DoneWhen(TRUE);
	END_IF;		





    CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q );

END_IF

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

