VAR_INPUT
    inEnable : BOOL;
END_VAR
VAR_OUTPUT
END_VAR
VAR_IN_OUT
    inoData : TcoKrc4_IO_v_5_x_x;
END_VAR
VAR


	{attribute addProperty Name "<#Status#>"}
    {attribute clr [ReadOnly()]}
    _status : TcoKukaRobotics_Status_v_5_x_x;
	{attribute addProperty Name "<#Control#>"}
	_control 	: TcoKukaRobotics_Control_v_5_x_x;
