	{attribute addProperty Name "<#PN Error#>"}
    {attribute clr [ReadOnly()]}
    _pnError : BOOL;

	_someTaskIsActive: BOOL;

	_stopTasksAreActive: BOOL;
END_VAR
VAR
	{attribute addProperty Name "<#Start at Main#>"}
    _startAtMainTask : StartAtMainTask(THIS^);

	 {attribute addProperty Name "<#Start motors and program#>"}
    _startMotorsAndProgramTask : StartMotorsAndProgramTask(THIS^);

	 {attribute addProperty Name "<#Start program#>"}
    _startProgramTask : StartProgramTask(THIS^);

	{attribute addProperty Name "<#Start motors#>"}
    _startMotorsTask : StartMotorsTask(THIS^);

  	{attribute addProperty Name "<#Start movements#>"}
    _startMovementsTask : StartMovementsTask(THIS^);

	{attribute addProperty Name "<#Start motors program and movements#>"}
    _startMotorsProgramAndMovementsTask : StartMotorsProgramAndMovementsTask(THIS^);




	 {attribute addProperty Name "<#Stop movements#>"}
    _stopMovementsTask : StopMovementsTask(THIS^);

	 {attribute addProperty Name "<#Stop movenents and program#>"}
    _stopMovementsAndProgramTask : StopMovementsAndProgramTask(THIS^);

	{attribute addProperty Name "<#Stop program#>"}
    _stopProgramTask : StopProgramTask(THIS^);

	{attribute addProperty Name "<#Stop motors#>"}
    _stopMotorsTask : StopMotorsTask(THIS^);


    {attribute addProperty Name "<#Restore#>"}
    _restoreTask : TcoCore.TcoTask(THIS^);







END_VAR

VAR
	{attribute 'hide'}
	_sb : TcoCore.StringBuilder;
END_VAR
IF NOT __ISVALIDREF(inoData) THEN
    Messenger.Post('Invalid reference', TcoCore.eMessageCategory.ProgrammingError);
    RETURN;
END_IF

SUPER^(inPnIoBoxState := THIS^.inoData.PnIoBoxState,inPnIoBoxDiag := THIS^.inoData.PnIoBoxDiag);
_pnError:= not _profinetReady;


UpdateStatus();
_stopTasksAreActive :=  _stopMovementsTask.Busy 
			AND _stopMovementsAndProgramTask.Busy 
			AND _stopProgramTask.Busy
			AND _stopMotorsTask.Busy;

_startAtMainTask.Enabled:=NOT _stopTasksAreActive;
_startAtMainTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);


_startProgramTask.Enabled:=NOT _stopTasksAreActive;
_startProgramTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);

_startMotorsTask.Enabled:=NOT _stopTasksAreActive AND NOT _startMotorsProgramAndMovementsTask.Busy AND NOT _startMotorsAndProgramTask.Busy;
_startMotorsTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);

_startMotorsAndProgramTask.Enabled:=NOT _stopTasksAreActive AND NOT _startProgramTask.Busy AND NOT _startMotorsTask.Busy;
_startMotorsAndProgramTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);

_startMovementsTask.Enabled:=NOT _startMotorsProgramAndMovementsTask.Busy AND NOT _stopMotorsTask.Busy;
_startMovementsTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);

_startMotorsProgramAndMovementsTask.Enabled:=NOT _startMovementsTask.Busy  AND NOT _stopMotorsTask.Busy;
_startMotorsProgramAndMovementsTask(refStartMotorsAndProgramTask:=_startMotorsAndProgramTask, inoConfig:=_config,inoControl:=_control,inoStatus:=_status);


_stopMovementsTask.Enabled:=TRUE;
_stopMovementsTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);

_stopMotorsTask.Enabled:=TRUE;
_stopMotorsTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);

_stopProgramTask.Enabled:=TRUE;
_stopProgramTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);

_stopMovementsAndProgramTask.Enabled:=NOT _stopProgramTask.Busy AND NOT _stopProgramTask.Busy;
_stopMovementsAndProgramTask(inoConfig:=_config,inoControl:=_control,inoStatus:=_status);



//*************RESTORE********************

_restoreTask.Enabled := TRUE;
IF _restoreTask.Execute() THEN
	Restore();
	_restoreTask.DoneWhen(TRUE);
END_IF
//****************************************

_someTaskIsActive := _startAtMainTask.Busy 
					OR _startMotorsAndProgramTask.Busy
					OR _startMovementsTask.Busy
					OR _startMovementsTask.Busy
					OR _stopMovementsTask.Busy
					OR _stopMovementsAndProgramTask.Busy
					OR _stopProgramTask.Busy;


//do not publish diagnostic message when component is not used
IF _someTaskIsActive THEN

	IF(NOT _status.State.AlarmStopActive) THEN
		Messenger.Error('<#Emergency stop active#>');
	END_IF;
	IF(NOT _status.State.UserSafetySwitchClosed) THEN
		Messenger.Warning('<#Safety Error #>');
	END_IF;


END_IF;


IF(_status.State.Error) THEN Messenger.Error(_sb.Clear().Append('<#Robot reported an error: #>').Append(UDINT_TO_STRING(_status.State.EventId)).Append(' |[[0]AdvancedDiagnosticMessage]|').Append('.').Append('For details see the service mode').ToString()); END_IF;


UpdateControl();
END_FUNCTION_BLOCK

FUNCTION_BLOCK PUBLIC ABSTRACT TcoKukaRoboticsTask EXTENDS TcoCore.TcoTask 
VAR_IN_OUT
    inoConfig 	: TcoKukaRobotics_Config_v_5_x_x;
	inoControl 	: TcoKukaRobotics_Control_v_5_x_x;
	inoStatus 	: TcoKukaRobotics_Status_v_5_x_x;	
END_VAR
VAR
	_errorMessage:TcoCore.TcoMessenger(THIS^);
    {attribute 'hide'} 
	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
	{attribute 'hide'} 
	_timer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
	{attribute 'hide'}
	_blink:TcoUtilities.TcoBlinker(THIS^);
END_VAR

END_FUNCTION_BLOCK

FUNCTION_BLOCK StartAtMainTask EXTENDS TcoKukaRoboticsTask
IF Execute() THEN 
	_blink(inOnTime:=T#500MS,inOffTime:=T#500MS);

	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE
			_progress := _progress + 1;
		END_IF

	END_IF

	IF _progress = 1 THEN

		inoControl.StartAtMain :=not inoStatus.State.PpMoved and  _blink.outQ;
		_varInfo :=__VARINFO( inoStatus.State.PpMoved);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.PpMoved).Warning(_sb.Clear().Append('<#Waiting program pointer changed! #>').Append(_varInfo.Symbol).ToString());

		IF inoStatus.State.PpMoved  THEN
			inoControl.StartAtMain :=FALSE;
			_progress:=0;
		END_IF
	END_IF
    DoneWhen(inoStatus.State.PpMoved );
    CallTimers(TRUE);


	THIS^.ThrowWhen(_errorTimer.Q );

END_IF;

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK StartMotorsAndProgramTask EXTENDS TcoKukaRoboticsTask
IF Execute() THEN
	 _blink(inOnTime:=T#500MS,inOffTime:=T#500MS);

  	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE

			_progress := _progress + 1;

		END_IF

	END_IF
	IF _progress = 1 THEN

		_varInfo :=__VARINFO( inoStatus.State.UserSafetySwitchClosed);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.UserSafetySwitchClosed).Warning(_sb.Clear().Append('<#Waiting for signal#>').Append(_varInfo.Symbol).ToString());
		IF  inoStatus.State.UserSafetySwitchClosed THEN
			_progress := _progress + 1;
		END_IF;
	END_IF;
	IF _progress = 2 THEN

		_varInfo :=__VARINFO( inoStatus.State.AlarmStopActive);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.AlarmStopActive).Warning(_sb.Clear().Append('<#Waiting for signal#>').Append(_varInfo.Symbol).ToString());
		IF  inoStatus.State.AlarmStopActive THEN
			_progress := _progress + 1;
		END_IF;
	END_IF;

	IF _progress = 3 THEN	

		_varInfo :=__VARINFO( inoStatus.State.DrivesReady);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.DrivesReady).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());
		inoControl.DrivesOff:=TRUE;		
		inoControl.DrivesOn:=_blink.outQ;	
		IF inoStatus.State.DrivesReady  THEN
			 inoControl.DrivesOn:=FALSE;
			_progress := _progress + 1;
		END_IF
	END_IF;		


	IF _progress = 4 THEN	
		Messenger.Debug('<#Robot Error Reset and Move Enable#>');
		inoControl.MoveEnable:=TRUE;
		inoControl.ErrorConfirmation := inoStatus.State.StopMess AND _blink.outQ;
		_varInfo :=__VARINFO( inoStatus.State.StopMess);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND  inoStatus.State.StopMess).Warning(_sb.Clear().Append('<#Waiting for signal#>').Append(_varInfo.Symbol).Append(' is OFF').ToString());

		_varInfo :=__VARINFO( inoStatus.State.RcReady);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.RcReady).Warning(_sb.Clear().Append('<#Waiting for signal#>').Append(_varInfo.Symbol).ToString());

		IF NOT inoStatus.State.StopMess AND inoStatus.State.RcReady THEN
			inoControl.ErrorConfirmation:=FALSE;
			_progress := _progress + 1;
		END_IF
	END_IF;

	IF _progress = 5 THEN

		inoControl.ActivateInterface:=TRUE;
		_varInfo :=__VARINFO( inoStatus.State.InterfaceActivated);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.InterfaceActivated).Warning(_sb.Clear().Append('<#Waiting for signal#>').Append(_varInfo.Symbol).ToString());
		IF  inoStatus.State.InterfaceActivated THEN
			_progress := _progress + 1;
		END_IF;
	END_IF;

	IF _progress = 6 THEN	
		IF inoStatus.State.StopMess OR inoStatus.State.AlarmStopActive OR NOT  inoStatus.State.RcReady THEN 
			_progress := 1;
		END_IF
		inoControl.ExternalStart:=_blink.outQ;
		_varInfo :=__VARINFO( inoStatus.State.ProActive);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.ProActive).Warning(_sb.Clear().Append('<#Waiting for program running signal! #>').Append(_varInfo.Symbol).ToString());


		IF  inoStatus.State.ProActive  THEN
				inoControl.ExternalStart:=FALSE;
		END_IF
	END_IF;

    DoneWhen(inoStatus.State.ProActive AND inoStatus.State.DrivesReady AND NOT inoStatus.State.StopMess);
    CallTimers(TRUE);
	THIS^.ThrowWhen(_errorTimer.Q );

END_IF

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK StartMotorsProgramAndMovementsTask EXTENDS TcoKukaRoboticsTask
VAR_INPUT
	refStartMotorsAndProgramTask: REFERENCE TO StartMotorsAndProgramTask;
END_VAR 
VAR
     _moveParams:TcoAbstractions.TcoRoboticsMovementsParams;


END_VAR
VAR
	_startMotorsAndProgramTask: REFERENCE TO StartMotorsAndProgramTask;
END_VAR
IF NOT __ISVALIDREF(refStartMotorsAndProgramTask)  THEN
    Messenger.Post('<#Invalid reference StartMotorAndProgramTask#>', TcoCore.eMessageCategory.ProgrammingError);
    RETURN;
END_IF
_startMotorsAndProgramTask REF= refStartMotorsAndProgramTask;

IF Execute() THEN
	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
			ELSE
			_progress := _progress + 1;
		END_IF

	END_IF

	IF _progress = 1 THEN
		IF _startMotorsAndProgramTask.Invoke().Done THEN
			_progress := _progress + 1;
		END_IF

	END_IF;


	IF _progress = 2 THEN
		inoControl.GlobalSpeed := _moveParams.GlobalSpeed;
		inoControl.ToolNo := _moveParams.ToolNo;
		inoControl.WorkobjectNo := _moveParams.WorkobjectNo;
		inoControl.PointNo := _moveParams.PointNo;
		inoControl.UserSpecSpeed1 := _moveParams.UserSpecSpeed1;
		inoControl.UserSpecSpeed2 := _moveParams.UserSpecSpeed2;
		inoControl.Coordinates := _moveParams.Coordinates; 		

		inoControl.ActionNo := 254;
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			_progress:=_progress + 1;
		END_IF
	END_IF;	
	IF _progress = 3 THEN
		IF 	inoStatus.State.GlobalSpeed = _moveParams.GlobalSpeed AND
			inoStatus.State.ToolNo = _moveParams.ToolNo AND
			inoStatus.State.WorkobjectNo = _moveParams.WorkobjectNo AND
			inoStatus.State.PointNo = _moveParams.PointNo AND
			inoStatus.State.UserSpecSpeed1 = _moveParams.UserSpecSpeed1 AND
			inoStatus.State.UserSpecSpeed2 =_moveParams.UserSpecSpeed2 AND
			TcoAbstractions.CoordinatesAreEqual(inoStatus.State.Coordinates,_moveParams.Coordinates,0.01,0.01,0.01,0.01,0.01,0.01) THEN
			inoControl.ActionNo := 253;
			_progress:=_progress + 1;
		END_IF
	END_IF;	

	IF _progress = 4 THEN
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			_progress:=_progress + 1;
		END_IF
	END_IF;	


	IF _progress = 5 THEN

		Messenger.Info(CONCAT('<#Moving to position ID#>: ', INT_TO_STRING(_moveParams.ActionNo)));
		inoControl.ActionNo := _moveParams.ActionNo;
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			inoControl.ActionNo :=255;
				_progress := _progress + 1;
		END_IF
	END_IF;		

	IF _progress = 6 THEN
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			 DoneWhen(TRUE);
		END_IF
	END_IF;		

   CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q );
END_IF

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

