FUNCTION_BLOCK TcoTurnTableTask EXTENDS TcoCore.TcoTask
VAR_INPUT
	inSafetyCondition:BOOL;
END_VAR
VAR_IN_OUT

	inoInPosition : BOOL;
	inoInPrecisePosition : BOOL;
	inoEnableTurn : BOOL;
	inoStartTurn : BOOL;
	inoConfig : TcoCarouselConfig;
	inoStatus : TcoCarouselStatus;
END_VAR

VAR
 	{attribute 'hide'} 
	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;

	_notInPositionMessage : TcoCore.TcoMessenger(THIS^);	
END_VAR
IF (THIS^.Execute()) THEN


	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoInPosition) THEN
			_varInfo :=__VARINFO(inoInPosition);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoInPrecisePosition) THEN                                              
			_varInfo :=__VARINFO(inoInPrecisePosition);                                                
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoEnableTurn) THEN                                              
			_varInfo :=__VARINFO(inoEnableTurn);                                                
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStartTurn) THEN                                              
			_varInfo :=__VARINFO(inoStartTurn);                                                
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();

		ELSE
			_progress := _progress + 1;
		END_IF

	END_IF
	IF _progress=1 THEN	
		_notInPositionMessage.OnCondition(NOT inoInPosition).Error('<#Rotatiting started , but table is not in default position! Acknowledge this alarm if you still want to turn! #>').Pin();
		_progress:=10;

	END_IF;



	IF _progress=10 THEN	
		Messenger.Info('<#Calulate next expected Id position#>');
		IF inoStatus.CurrentPosition <> 0 THEN
			inoStatus.ExpectedNextPosition := GetIdentifierAtPosition( inoConfig.NumberOfPositions,inoStatus.Positions);	
		END_IF;

		Messenger.OnCondition(inoStatus.CurrentPosition=0  AND inoInPosition).Error('<#Incorrectly coded current position. Check configuration of code bits! #>').Pin();

		IF	inoStatus.CurrentPosition <> 0 AND inoInPosition THEN
			_progress := 20;
		ELSIF NOT 	_notInPositionMessage.Pinned THEN
			_progress:=20;
			_notInPositionMessage.UnPin();

		END_IF;		
	END_IF;

	IF _progress=20 THEN	
		inoEnableTurn:=TRUE; 
		inoStartTurn:=TRUE;	
		Messenger.Info('<#Table turning. Trying to leave sensor#>');

		IF NOT inoInPosition THEN
			inoEnableTurn:=FALSE;	
			_progress :=  _progress+10;				
		END_IF
	END_IF;


	IF _progress=30 THEN	
		Messenger.Info('<#Table turning. Trying to reach sensor table in positon.#>');
		inoStartTurn:=TRUE;	
		IF inoInPosition THEN
			inoEnableTurn:=FALSE; 
			inoStartTurn:=FALSE;	
			_progress :=  _progress+10;				
		END_IF
	END_IF;

	IF _progress=40 THEN	
		Messenger.OnCondition(inoStatus.CurrentPosition > 0 AND_THEN inoStatus.ExpectedNextPosition  <>  GetIdentifierAtPosition(1,inoStatus.Positions)).
			Error(_sb.Clear().Append('<#Table after turn does not have expected coding. Expected id at position #1 is#> ').Append( UINT_TO_STRING(inoStatus.ExpectedNextPosition)).ToString()).Pin();

		IF(inoStatus.CurrentPosition > 0 AND inoStatus.ExpectedNextPosition = GetIdentifierAtPosition(1,inoStatus.Positions)) THEN

			THIS^.DoneWhen(TRUE);	

		END_IF;	
	END_IF;


	CallTimers(TRUE);
	THIS^.ThrowWhen(_errorTimer.Q);	

END_IF


IF NOT inSafetyCondition THEN
	inoEnableTurn:=FALSE; 
	inoStartTurn:=FALSE;	
	Messenger.Error('<#Safety conditions to turn the table are not met.#>').Pin();
END_IF
END_FUNCTION_BLOCK

(*~
	<docu>
		<summary>
				Generic component for monitoring of a continuous signal input. (e.g. AnalogSensor).												
		</summary>				
	</docu>	
~*)	
FUNCTION_BLOCK TcoAi EXTENDS TcoCore.TcoComponent
VAR_IN_OUT
	(*~
	<docu>
		<summary>
			Input  continious signal. Typically an `%I* : INT` or `%I* : DINT`  variable. 												
		</summary>				
	</docu>	
	~*)
	inoSignal : DINT;

END_VAR

VAR
	(*~
	<docu>
		<summary>
			Backing variable for signal; this variable is used directly by the component. It updates `inoSingal` in FB body call. 												
		</summary>				
	</docu>	
	~*)
	_signal : DINT;	
END_VAR

VAR
	(*~
	<docu>
		<summary>
			Provides information about the input signal of this instance of `TcoAi`.											
		</summary>				
	</docu>	
	~*)
	{attribute addProperty Name "<#Signal#>"}
	_signalInfo : TcoCore.TcoSignalInfo;

	(*~
	<docu>
		<summary>
			Contains information about the settings and configuration of this instance of `TcoAi`.								
		</summary>				
	</docu>	
	~*)
	{attribute addProperty Name "<#Config#>"}
	_config : TcoAiConfig;

	(*~
	<docu>
		<summary>
			Contains information about the status if this instance of `TcoAi`.								
		</summary>				
	</docu>	
	~*)	
	{attribute addProperty Name "<#Status#>"}
	_status : TcoAiStatus;	


	_rawRange             : REAL;
	_realRange            : REAL;
	_scaled               : REAL;
END_VAR
IF (__ISVALIDREF(inoSignal)) THEN
    _signalInfo.GetSignalInfo(SIZEOF(inoSignal), ADR(inoSignal));
    _signal := inoSignal;
END_IF;

//------------------scale-------------------------
_rawRange  := DINT_TO_REAL(_config.RawHigh - _config.RawLow);
_realRange := config.RealHigh - Config.RealLow;
_scaled    := 0;

IF (_rawRange = 0) THEN
    Messenger.Warning('<#Division by zero: Verify values defined in config! (RawHigh,RawLow)#>');
    RETURN;
END_IF

IF (Config.Gain = 0) THEN
    Messenger.Warning('<#Invalid data: Gain is not defined!#>');
END_IF

_scaled := (DINT_TO_REAL(_signal - _config.RawLow)) / _rawRange;

_scaled := _scaled * _realRange;
_scaled := _scaled + _config.RealLow;

_scaled := _scaled * _config.Gain + _config.Offset;
//------------------------------------------------

IF (_scaled > _config.RealHigh) AND (_config.Gain <> 1 OR _config.Offset <> 0) THEN
    Messenger.Warning('<#Out of boundaries,check correction parameters (Gain,Ofset) in config!#>');
ELSIF (_scaled < _config.RealLow) AND (_config.Gain <> 1 OR _config.Offset <> 0) THEN
    Messenger.Warning('<#Out of boundaries,check correction parameters (Gain,Ofset) in config!#>');
END_IF

_status.RawRange  := _rawRange;
_status.RealRange := _realRange;
_status.Scaled    := _scaled;
END_FUNCTION_BLOCK

