FUNCTION_BLOCK Jog EXTENDS TcoCore.TcoObject IMPLEMENTS ITcoDriveSimple, TcoCore.ITcoServiceable
VAR_INPUT
    inIsServiceMode : BOOL;
END_VAR
VAR
    {attribute 'hide'}
    _axisRef : REFERENCE TO TcoAxisRef;
    {attribute 'hide'}
    _mcJog : Tc2_MC2.MC_Jog;
    {attribute addProperty Name "<#Jog forward#>"}
    {attribute addProperty StateOnDesc "<#Running#>"}
    {attribute addProperty StateOffDesc "<#Stopped#>"}
    _jogForwardTask : TcoCore.TcoMomentaryTask(THIS^);
    {attribute addProperty Name "<#Jog backwards#>"}
    {attribute addProperty StateOnDesc "<#Running#>"}
    {attribute addProperty StateOffDesc "<#Stopped#>"}
    _jogBackwardsTask : TcoCore.TcoMomentaryTask(THIS^);
    {attribute addProperty Name "<#Jog mode#>"}
    _jogMode : eJogMode;
    {attribute addProperty Name "<#Position#>"}
    _position : LREAL;
    {attribute addProperty Name "<#Velocity#>"}
    _velocity : LREAL;
    {attribute addProperty Name "<#Acceleration#>"}
    _acceleration : LREAL;
    {attribute addProperty Name "<#Deceleration#>"}
    _deceleration : LREAL;
    {attribute addProperty Name "<#Jerk#>"}
    _jerk : LREAL;
	{attribute 'hide'}
	_dummyPreconditionOK : BOOL;

	_serviceContexCycle : ULINT;
	_myContextCycleCount : ULINT;
	_inServiceMode : BOOL;
END_VAR
IF NOT __ISVALIDREF(_axisRef) THEN
    IF __ISVALIDREF(DriveRef) THEN
        _axisRef REF= DriveRef.AxisRef;
    ELSE
        RETURN;
    END_IF
END_IF

_jogForwardTask.Enabled := inIsServiceMode;
_jogBackwardsTask.Enabled := inIsServiceMode;
_jogForwardTask.Run();
_jogBackwardsTask.Run();


IF _jogForwardTask.State THEN
    _dummyPreconditionOK := DriveRef._power._mcPower.Enable_Positive;

    IF NOT DriveRef._movementState.JogPreconditionsOk(_jogForwardTask, _dummyPreconditionOK) THEN
        Messenger.Error('Movements to positive direction are disabled');
        RETURN;
    END_IF
END_IF

IF _jogBackwardsTask.State THEN
    _dummyPreconditionOK := DriveRef._power._mcPower.Enable_Negative;

    IF NOT DriveRef._movementState.JogPreconditionsOk(_jogBackwardsTask, _dummyPreconditionOK) THEN
        Messenger.Error('Movements to negative direction are disabled');
        RETURN;
    END_IF
END_IF

_mcJog(Axis := _axisRef,
    JogForward := _jogForwardTask.State AND NOT _mcJog.Error,
    JogBackwards := _jogBackwardsTask.State AND NOT _mcJog.Error,
    Mode := _jogMode,
    Position := _position,
    Velocity := _velocity,
    Acceleration := _acceleration,
    Deceleration := _deceleration,
    Jerk := _jerk,
    Done =>,
    Busy =>,
    Active =>,
    CommandAborted =>,
    Error =>,
    ErrorID =>);

IF _mcJog.Done OR _mcJog.CommandAborted OR _mcJog.Error THEN
    THIS^.DriveRef._movementState.Restore();
END_IF

IF NOT _axisRef.Status.Error AND _mcJog.Error THEN
    DriveRef.SetErrorID(_mcJog.ErrorID);
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK Power EXTENDS TcoCore.TcoObject IMPLEMENTS ITcoDriveSimple
VAR_INPUT
    inEnable : BOOL;
    inEnablePositive : BOOL;
    inEnableNegative : BOOL;
    inOverride : LREAL;
	inIsServiceMode : BOOL;
END_VAR
VAR
    {attribute addProperty Name "<#Power enable#>"}
	{attribute addProperty StateOnDesc "<#Enabled#>"}
	{attribute addProperty StateOffDesc "<#Disabled#>"}
    _driveEnableLocalTask : TcoCore.TcoToggleTask(THIS^, FALSE);
    {attribute addProperty Name "<#Enable positive#>"}
	{attribute addProperty StateOnDesc "<#Enabled#>"}
	{attribute addProperty StateOffDesc "<#Disabled#>"}
    _driveEnablePositiveLocalTask : TcoCore.TcoToggleTask(THIS^, FALSE);
    {attribute addProperty Name "<#Enable negative#>"}
	{attribute addProperty StateOnDesc "<#Enabled#>"}
	{attribute addProperty StateOffDesc "<#Disabled#>"}
    _driveEnableNegativeLocalTask : TcoCore.TcoToggleTask(THIS^, FALSE);
END_VAR
VAR
    {attribute 'hide'}
    _axisRef : REFERENCE TO TcoAxisRef;
    {attribute 'hide'}
    _mcPower : Tc2_MC2.MC_Power;
    {attribute addProperty Name "<#Drive power override#>"}
	{attribute addProperty StateOnDesc "<#Local control#>"}
	{attribute addProperty StateOffDesc "<#Global control#>"}
    _drivePowerOverrideTask : TcoCore.TcoToggleTask(THIS^, FALSE);
    {attribute 'hide'}
    _powerOverride : ePowerOverride;
    {attribute 'hide'}
    _powerOverridePV : ePowerOverride;
    {attribute addProperty Name "<#Override#>"}
    _override : LREAL;
    {attribute 'hide'}
    _enable : BOOL;
    {attribute 'hide'}
    _enablePositive : BOOL;
    {attribute 'hide'}
    _enableNegative : BOOL;
END_VAR
IF NOT __ISVALIDREF(_axisRef) THEN
    IF __ISVALIDREF(DriveRef) THEN
        _axisRef REF= DriveRef.AxisRef;
    ELSE
        RETURN;
    END_IF
END_IF

_drivePowerOverrideTask.Enabled := inIsServiceMode;
_drivePowerOverrideTask.Run();

IF _drivePowerOverrideTask.IsOff THEN
	_powerOverride := ePowerOverride.Global_control;
ELSE
	_powerOverride := ePowerOverride.Local_control;
END_IF;	

_driveEnableLocalTask.Run();
_driveEnablePositiveLocalTask.Run();
_driveEnableNegativeLocalTask.Run();

//Take values from Global
IF _powerOverridePV = ePowerOverride.Global_control AND _powerOverride = ePowerOverride.Local_control THEN
    _override := inOverride;
	IF inEnable THEN
		_driveEnableLocalTask.On();
	ELSE 
		_driveEnableLocalTask.Off();
	END_IF
	IF inEnablePositive THEN
		_driveEnablePositiveLocalTask.On();
	ELSE 
		_driveEnablePositiveLocalTask.Off();
	END_IF
	IF inEnableNegative THEN
		_driveEnableNegativeLocalTask.On();
	ELSE 
		_driveEnableNegativeLocalTask.Off();
	END_IF
END_IF

IF _powerOverridePV = ePowerOverride.Local_control AND _powerOverride = ePowerOverride.Global_control THEN
	IF inEnable THEN
		_driveEnableLocalTask.On();
	ELSE 
		_driveEnableLocalTask.Off();
	END_IF
	IF inEnablePositive THEN
		_driveEnablePositiveLocalTask.On();
	ELSE 
		_driveEnablePositiveLocalTask.Off();
	END_IF
	IF inEnableNegative THEN
		_driveEnableNegativeLocalTask.On();
	ELSE 
		_driveEnableNegativeLocalTask.Off();
	END_IF
	_driveEnableLocalTask.Enabled :=FALSE;
	_driveEnablePositiveLocalTask.Enabled :=FALSE;
	_driveEnableNegativeLocalTask.Enabled :=FALSE;
END_IF

_powerOverridePV := _powerOverride;

IF _powerOverride = ePowerOverride.Global_control THEN
    _mcPower(Axis := _axisRef,
        Enable := inEnable,
        Enable_Positive := inEnablePositive,
        Enable_Negative := inEnableNegative,
        Override := inOverride,
        BufferMode := Tc2_MC2.MC_BufferMode.MC_Aborting);
END_IF

IF _powerOverride = ePowerOverride.Local_control AND inIsServiceMode THEN
	_driveEnableLocalTask.Enabled := TRUE;
	_driveEnablePositiveLocalTask.Enabled := TRUE;
	_driveEnableNegativeLocalTask.Enabled := TRUE;


    _mcPower(Axis := _axisRef,
        Enable := _driveEnableLocalTask.State,
        Enable_Positive := _driveEnablePositiveLocalTask.State,
        Enable_Negative := _driveEnableNegativeLocalTask.State,
        Override := _override,
        BufferMode := Tc2_MC2.MC_BufferMode.MC_Aborting);

END_IF

IF NOT inIsServiceMode THEN
	IF _drivePowerOverrideTask.IsOn THEN
		_drivePowerOverrideTask.Off();
	END_IF
	_powerOverride := ePowerOverride.Global_control;
	_drivePowerOverrideTask.Enabled :=FALSE;
	_driveEnableLocalTask.Enabled :=FALSE;
	_driveEnablePositiveLocalTask.Enabled :=FALSE;
	_driveEnableNegativeLocalTask.Enabled :=FALSE;
END_IF

IF NOT _axisRef.Status.Error AND _mcPower.Error THEN
	DriveRef.SetErrorID(_mcPower.ErrorID);
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoDriveSimple EXTENDS TcoCore.TcoComponent IMPLEMENTS ITcoDriveSimple
VAR_INPUT
    inEnable : BOOL;
    inEnablePositive : BOOL;
    inEnableNegative : BOOL;
    inCalibrationCam : BOOL;
END_VAR
VAR_OUTPUT
END_VAR
VAR_IN_OUT
