VAR
    {attribute 'hide'} 
	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
END_VAR
IF Execute() THEN
	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoIoData) THEN
			_varInfo :=__VARINFO(inoIoData);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoResults) THEN                                              
			_varInfo :=__VARINFO(inoResults);                                                
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 1 THEN
		THIS^.inoStatus.ActionDescription := '<#Clearing result data running.#>'; 
		CallTimers(FALSE);
		_progress := _progress + 1;
	END_IF

	IF _progress = 2 THEN
		THIS^.inoIoData.AcquisitionControl.AcquisitionTriggerEnable := FALSE;
		THIS^.inoIoData.AcquisitionControl.AcquisitionTrigger := FALSE;
		THIS^.inoIoData.InspectionControl.AcknowledgeInspectionResults := TRUE;
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the result data cleared!#>').Pin();
		THIS^.inoResults.InspectionId := 0;
		THIS^.inoResults.ResultCode := 0;
		IF Tc2_System.MEMSET(destAddr:= ADR(THIS^.inoResults.InspectionResults) , fillByte:= 0 , n:= SIZEOF(THIS^.inoResults.InspectionResults)) >0 THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 3 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal ResultsValid reseted!#>').Pin(); 
		IF NOT THIS^.inoIoData.InspectionStatus.ResultsValid THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 4 THEN
		THIS^.inoIoData.InspectionControl.AcknowledgeInspectionResults := FALSE;
		THIS^.DoneWhen(TRUE);
		CallTimers(FALSE);
		_progress := 0;
	END_IF

	CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q);
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoInsightSoftEvent_v_5_x_x EXTENDS TcoCore.TcoTask
VAR_IN_OUT
	inoIoData	: TcoInsightIO_v_5_x_x;
    inoConfig	: TcoInsightConfig_v_5_x_x;
	inoStatus	: TcoInsightStatus_v_5_x_x;	
END_VAR
VAR
   {attribute addProperty Name "<#Soft event number#>"}
	_softEventNumber : UINT;
END_VAR
VAR
    {attribute 'hide'} 
	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
    {attribute 'hide'} 
	_inspectionCompleted : BOOL;
END_VAR
IF Execute() THEN
	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoIoData) THEN
			_varInfo :=__VARINFO(inoIoData);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 1 THEN
		CallTimers(FALSE);
		IF _softEventNumber > 7 THEN
			Messenger.Programming(_sb.Clear().Append('<#SoftEvent number: (').Append(UINT_TO_STRING(_softEventNumber)).Append(') is greater than the maximal value of 7!#>').ToString()).Pin();
			THIS^.ThrowWhen(TRUE);
		ELSE	
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 2 THEN
		THIS^.inoStatus.ActionDescription := _sb.Clear().Append('<#SoftEvent (number: ').Append(UINT_TO_STRING(THIS^._softEventNumber)).Append(') is running.#>').ToString();
		CallTimers(FALSE);
		_progress := _progress + 1;
	END_IF

	IF _progress = 3 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning(_sb.Clear().Append('<#Waiting for the signal TriggerSoftEvent[').Append(UINT_TO_STRING(THIS^._softEventNumber)).Append('] to be set!#>').ToString()).Pin(); 
		THIS^.inoIoData.SoftEventControl.TriggerSoftEvent[_softEventNumber] := TRUE;
		IF THIS^.inoIoData.SoftEventControl.TriggerSoftEventAcknowledge[_softEventNumber] THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 4 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning(_sb.Clear().Append('<#Waiting for the signal TriggerSoftEvent[').Append(UINT_TO_STRING(THIS^._softEventNumber)).Append('] to be reseted!#>').ToString()).Pin(); 
		THIS^.inoIoData.SoftEventControl.TriggerSoftEvent[_softEventNumber] := FALSE;
		IF NOT THIS^.inoIoData.SoftEventControl.TriggerSoftEventAcknowledge[_softEventNumber] THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 5 THEN
		THIS^.DoneWhen(TRUE);
		_progress := 0;
	END_IF

	CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q);

END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoInsightTrigger_v_5_x_x EXTENDS TcoCore.TcoTask
VAR_IN_OUT
	inoIoData	: TcoInsightIO_v_5_x_x;
    inoConfig	: TcoInsightConfig_v_5_x_x;
	inoStatus	: TcoInsightStatus_v_5_x_x;	
	inoResults	: TcoInsightResults_v_5_x_x;
END_VAR
VAR
    {attribute 'hide'} 
	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
    {attribute 'hide'} 
	_inspectionCompleted : BOOL;
    {attribute 'hide'} 
	_size : UINT;
END_VAR
IF Execute() THEN
	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoIoData) THEN
			_varInfo :=__VARINFO(inoIoData);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoResults) THEN                                              
			_varInfo :=__VARINFO(inoResults);                                                
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 1 THEN
		THIS^.inoStatus.ActionDescription := '<#Trigger running.#>'; 
		CallTimers(FALSE);
		THIS^.inoIoData.AcquisitionControl.AcquisitionTriggerEnable := TRUE;
		THIS^.inoIoData.AcquisitionControl.AcquisitionTrigger := FALSE;
		THIS^.inoIoData.AcquisitionControl.ClearExposureComplete := THIS^.inoIoData.AcquisitionStatus.ExposureComplete;
		THIS^.inoIoData.AcquisitionControl.SetOffline := FALSE;

		THIS^.inoIoData.InspectionControl.EnableResultsBuffering := FALSE; 
		THIS^.inoIoData.InspectionControl.AcknowledgeInspectionResults := THIS^.inoIoData.InspectionStatus.ResultsValid;
		THIS^.inoIoData.InspectionControl.ExtendedUserDataSet := FALSE;
		THIS^.inoIoData.InspectionControl.ExecuteCommand := FALSE;
		THIS^.inoIoData.InspectionControl.ClearError := THIS^.inoIoData.InspectionStatus.Error;

		THIS^.inoIoData.CommandControl.Command:=0;

		_progress := _progress + 1;
	END_IF

	IF _progress = 2 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal ExposureComplete to be reseted!#>').Pin(); 
		IF NOT THIS^.inoIoData.AcquisitionStatus.ExposureComplete THEN
			THIS^.inoIoData.AcquisitionControl.ClearExposureComplete := FALSE;
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 3 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal ResultsValid to be reseted!#>').Pin(); 
		IF NOT THIS^.inoIoData.InspectionStatus.ResultsValid THEN
			THIS^.inoIoData.InspectionControl.AcknowledgeInspectionResults := FALSE;
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 4 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal Error to be reseted!#>').Pin(); 
		IF NOT THIS^.inoIoData.InspectionStatus.Error THEN
			THIS^.inoIoData.InspectionControl.ClearError := FALSE;
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 5 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal AcquisitionTriggerReady to be set!#>').Pin(); 
		_inspectionCompleted := THIS^.inoIoData.InspectionStatus.InspectionCompleted;
		IF THIS^.inoIoData.AcquisitionStatus.AcquisitionTriggerReady THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 6 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal AcquisitionTriggerAcknowledge to be set!#>').Pin(); 
		THIS^.inoIoData.AcquisitionControl.AcquisitionTrigger := TRUE;
		IF THIS^.inoIoData.AcquisitionStatus.AcquisitionTriggerAcknowledge THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 7 THEN	
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal InspectionCompleted to be toggled!#>').Pin(); 
		THIS^.inoIoData.AcquisitionControl.AcquisitionTrigger := FALSE;
		IF THIS^._inspectionCompleted <> THIS^.inoIoData.InspectionStatus.InspectionCompleted THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 8 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the signal ResultsValid to be set!#>').Pin(); 
		IF THIS^.inoIoData.InspectionStatus.ResultsValid THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 9 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the InspectionResults to be copied!#>').Pin(); 
		THIS^.inoResults.InspectionId := THIS^.inoIoData.ResultsData.InspectionID;
		THIS^.inoResults.ResultCode := THIS^.inoIoData.ResultsData.ResultCode;
		_size := THIS^.inoConfig.ResultDataSize;
		IF  Tc2_System.MEMCPY(srcAddr := ADR(THIS^.inoIoData.ResultsData.InspectionResults) , destAddr:= ADR(THIS^.inoResults.InspectionResults) ,  n:= _size) > 0 AND 
			Tc2_System.MEMSET(destAddr:= ADR(THIS^.inoResults.InspectionResults) + _size, fillByte:= 0 , n:= SIZEOF(THIS^.inoResults.InspectionResults) - _size)>0 THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 10 THEN
		THIS^.inoIoData.AcquisitionControl.AcquisitionTrigger := FALSE;
		THIS^.inoIoData.InspectionControl.EnableResultsBuffering := FALSE;
		THIS^.inoIoData.InspectionControl.AcknowledgeInspectionResults := TRUE;
		THIS^.ThrowWhen(THIS^.inoIoData.InspectionStatus.Error);
		THIS^.DoneWhen(TRUE);
		_progress := 0;
	END_IF

	CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q OR _progress >4 AND THIS^.inoIoData.InspectionStatus.Error);	
END_IF
END_FUNCTION_BLOCK

