// Enhanced Motor Function Block with comprehensive features
FUNCTION_BLOCK FB_Motor
VAR_INPUT
    start : BOOL;
    stop : BOOL;
    speed_setpoint : REAL;
    enable : BOOL := TRUE;
    reset_fault : BOOL := FALSE;
END_VAR

VAR_OUTPUT
    running : BOOL;
    actual_speed : REAL;
    fault : BOOL;
    status : MotorState;
    runtime : TIME;
END_VAR

VAR
    internal_state : INT;
    motor_on : BOOL;
    fault_timer : TON;
    runtime_timer : TON;
    start_edge : R_TRIG;
    stop_edge : R_TRIG;
    speed_ramp : REAL := 0.0;
    last_scan_time : TIME;
END_VAR

// Edge detection for start/stop signals
start_edge(CLK := start);
stop_edge(CLK := stop);

// Motor control state machine
CASE status OF
    STOPPED:
        motor_on := FALSE;
        running := FALSE;
        actual_speed := 0.0;
        speed_ramp := 0.0;

        IF start_edge.Q AND enable AND NOT fault THEN
            status := STARTING;
        END_IF

    STARTING:
        motor_on := TRUE;
        running := TRUE;

        // Ramp up speed gradually
        IF speed_ramp < speed_setpoint THEN
            speed_ramp := speed_ramp + 1.0; // 1 unit per scan
        ELSE
            status := RUNNING;
        END_IF

        actual_speed := speed_ramp * 0.95; // 95% efficiency

        IF stop_edge.Q OR NOT enable THEN
            status := STOPPING;
        END_IF

    RUNNING:
        motor_on := TRUE;
        running := TRUE;
        actual_speed := speed_setpoint * 0.95; // 95% efficiency

        IF stop_edge.Q OR NOT enable THEN
            status := STOPPING;
        END_IF

    STOPPING:
        motor_on := FALSE;

        // Ramp down speed gradually
        IF speed_ramp > 0.0 THEN
            speed_ramp := speed_ramp - 2.0; // Faster ramp down
            actual_speed := speed_ramp * 0.95;
        ELSE
            status := STOPPED;
            running := FALSE;
            actual_speed := 0.0;
        END_IF

    FAULT:
        motor_on := FALSE;
        running := FALSE;
        actual_speed := 0.0;
        speed_ramp := 0.0;

        IF reset_fault THEN
            fault := FALSE;
            status := STOPPED;
        END_IF
END_CASE

// Fault detection with timer
fault_timer(IN := actual_speed > speed_setpoint * 1.2, PT := T#1s);
IF fault_timer.Q THEN
    fault := TRUE;
    status := FAULT;
END_IF

// Runtime calculation
runtime_timer(IN := running, PT := T#0s);
IF running THEN
    runtime := runtime + T#100ms; // Assuming 100ms scan time
END_IF

END_FUNCTION_BLOCK

