FUNCTION_BLOCK TimerFB
VAR_INPUT
    enable : BOOL;
    preset : TIME := T#5s;
END_VAR
VAR_OUTPUT
    done : BOOL;
END_VAR
VAR
    elapsed : TIME;
END_VAR

IF enable THEN
    elapsed := elapsed + T#100ms;
    done := elapsed >= preset;
ELSE
    elapsed := T#0s;
    done := FALSE;
END_IF;

